// ---------- what a tool call means ----------

type ToolArgs = {
  file_path?: string; notebook_path?: string; path?: string; command?: string; pattern?: string; glob?: string
  url?: string; query?: string; description?: string; skill?: string
  new_string?: string; content?: string; new_source?: string; edits?: Array<{ new_string?: string; old_string?: string }>
  old_string?: string
}

const TEST_RE = /\b(pytest|jest|vitest|mocha|go test|cargo test|dotnet test|mvn test|gradle test|npm (run )?test|pnpm test|yarn test|bun test|terraform test|invoke-pester|plugin test)\b/i

export function activityFor(tool: string, args: ToolArgs): Activity {
  switch (tool) {
    case 'Edit': case 'MultiEdit': case 'NotebookEdit': return 'edit'
    case 'Write': return 'write'
    case 'Read': return 'read'
    case 'Grep': case 'Glob': case 'LSP': return 'search'
    case 'WebFetch': case 'WebSearch': return 'web'
    case 'Agent': case 'Task': return 'agent'
    case 'Skill': return 'skill'
    case 'Bash': case 'PowerShell': case 'Monitor': {
      const c = args.command ?? ''
      if (TEST_RE.test(c)) return 'test'
      if (/\b(terraform|tofu|terragrunt)\b/i.test(c)) return 'terraform'
      if (/(^|&&|;|\|)\s*(git|gh)\b/i.test(c)) return 'git'
      return 'shell'
    }
    default: return 'none'
  }
}

export function moodFor(activity: Activity): Mood {
  switch (activity) {
    case 'edit': case 'write': return 'coding'
    case 'read': case 'search': case 'web': return 'reading'
    case 'shell': case 'git': case 'terraform': case 'test': return 'running'
    default: return 'working'
  }
}

// Scratch folders get a fresh dated name each time; they all count as one project.
export function normProject(name: string): string {
  return /^scratch-\d{4}-\d{2}-\d{2}/.test(name) ? 'scratch' : name
}

// A path relative to the cwd (case-insensitive prefix, forward slashes), or the path itself.
export function relativePath(path: string, cwd: string): string {
  const p = path.replace(/\\/g, '/')
  const c = cwd.replace(/\\/g, '/').replace(/\/+$/, '')
  if (c !== '' && p.toLowerCase().startsWith(c.toLowerCase() + '/')) return p.slice(c.length + 1)
  return p
}

// The text a project quest's "match" is looked for in, per activity.
export function matchTarget(activity: Activity, args: ToolArgs, cwd: string): string {
  switch (activity) {
    case 'search': return [args.path, args.pattern, args.glob].filter(Boolean).join(' ')
    case 'web': return args.url ?? args.query ?? ''
    case 'agent': return args.description ?? ''
    case 'edit': case 'write': case 'read': {
      const path = pathOf(args)
      return path ? relativePath(path, cwd) : ''
    }
    case 'shell': case 'terraform': case 'test': case 'git': return args.command ?? ''
    default: return ''
  }
}

const VERBS: Record<Activity, string> = {
  none: 'tool', edit: 'edit', write: 'write', read: 'read', search: 'search', web: 'web', shell: 'run',
  git: 'git', terraform: 'tf', test: 'test', agent: 'agent', skill: 'skill',
}

function pathOf(args: ToolArgs): string | undefined {
  return args.file_path ?? args.notebook_path ?? args.path
}

// The new text an edit puts in (Edit, MultiEdit, Write, NotebookEdit): looked at for silencing, never stored.
export function addedText(args: ToolArgs): string {
  const parts = [args.new_string, args.content, args.new_source, ...(Array.isArray(args.edits) ? args.edits.map(e => e?.new_string) : [])]
  return parts.filter((x): x is string => typeof x === 'string').join('\n').slice(0, 20_000)
}

// The text an edit replaces (Edit, MultiEdit): only compared for removed test definitions, never stored.
function removedText(args: ToolArgs): string {
  const parts = [args.old_string, ...(Array.isArray(args.edits) ? args.edits.map(e => e?.old_string) : [])]
  return parts.filter((x): x is string => typeof x === 'string').join('\n').slice(0, 20_000)
}

function extOf(path: string | undefined): string | null {
  const m = path ? /\.([a-z0-9]+)$/i.exec(path) : null
  return m?.[1] ? m[1].toLowerCase() : null
}

function detailFor(tool: string, args: ToolArgs): string {
  const path = pathOf(args)
  if (path) return path.split(/[\\/]/).pop() ?? path
  if (args.command) return args.command.length > 48 ? args.command.slice(0, 47) + '...' : args.command
  return args.description ?? args.skill ?? args.pattern ?? args.query ?? args.url ?? tool
}

function bar(value: number, goal: number, width: number): string {
  const filled = Math.max(0, Math.min(width, Math.round((value / Math.max(1, goal)) * width)))
  return '█'.repeat(filled) + '░'.repeat(width - filled)
}

// A quest's progress as shown: a words probe counts hundreds of words, so it shows the words.
function amount(q: Quest): string {
  const check = (q as Partial<ProjectQuest>).check
  const k = check?.type === 'probe' && check.probe === 'words' ? 100 : 1
  return `${Math.min(q.progress, q.goal) * k}/${q.goal * k}${k === 100 ? ' words' : ''}`
}

const PLANT_STEPS = [5, 25, 75, 200]

function plantStage(turns: number): number {
  return PLANT_STEPS.filter(step => turns >= step).length
}

function ratio(progress?: { value: number; goal: number }): number {
  return progress ? progress.value / Math.max(1, progress.goal) : 0
}

// The scene only changes at combo tiers, so a growing combo does not re-send the room.
function comboTier(n: number): number {
  return n >= 50 ? 50 : n >= 20 ? 20 : n >= 10 ? 10 : n >= 5 ? 5 : 0
}

function hatName(hat: HatId | null, custom: CustomHat | null): string {
  if (custom) return custom.name
  return hat ? HATS.find(item => item.id === hat)?.name ?? hat : ''
}

// ---------- terminal sprite: the block-character logo ----------

export function petAscii(mood: Mood, f: number): string[] {
  const blink = mood === 'sleeping' || (mood === 'idle' && f % 2 === 1) || (mood === 'working' && f % 8 === 0)
  const top = blink ? ' ▐█████▌ ' : ' ▐▛███▜▌ '
  const armsUp = mood === 'done' || mood === 'happy' || ((mood === 'coding' || mood === 'running' || mood === 'working') && f % 2 === 0)
  const mid = armsUp ? '▗▜█████▛▖' : '▝▜█████▛▘'
  const legs = '  ▘▘ ▝▝  '
  const art = [top, mid, legs]
  if (mood === 'sleeping') return [f % 4 < 2 ? '      z  ' : '     Z   ', ...art]
  if (mood === 'done' || mood === 'happy') return f % 2 === 0 ? [...art, '         '] : ['         ', ...art]
  if (mood === 'error') return [...(f % 2 === 0 ? art.map(l => ' ' + l.slice(0, -1)) : art), '         ']
  return [...art, '         ']
}

// ---------- module state (starts over on reload; the host keeps $.state and $.store) ----------

let token = 0
let tags = new Set<string>()
let project = ''
let cwdNow = ''
let isLoaded = false
let ensuring: Promise<void> | undefined
let turnStartedAt = 0
let turnTools = 0
let turnErrors = 0
let errorsInRow = 0
let lastActiveAt = 0
let lastToolAt = 0
let activeTools = 0
let turnCount = 0
let comboNow = 0
let petNow: PetState | undefined
let quipShownAt = 0
let lineHoldUntil = 0             // a turn's closing line holds the bubble until then
let usageShown: { kind: UsageNote; mood?: Mood; at: number } | undefined
let limitsSeeded = false          // the limits came from the store: the first measure without any drops them
let usagePending: { kind: UsageNote; mood?: Mood } | undefined // waits for the turn's line to end
let profileCache: Profile | undefined
let keys: ProjectKeys | undefined // this project folder's store keys, set in setup
let seenProfile = ''              // JSON of the stored profile this session last read or wrote
let seenBoard = ''                // the same for the board
let isFrozen = false              // the stored profile is from a newer version: show it, never write it
let gameQueue: Promise<unknown> = Promise.resolve()
let postQueue: Promise<unknown> = Promise.resolve()
let verbCache = { key: '', at: 0, verb: 'Clawding' }
let tick = 0
let shown: { mood: Mood; activity: Activity; at: number; walk?: Walk } = { mood: 'idle', activity: 'none', at: 0 }
let latest: { mood: Mood; activity: Activity } = { mood: 'idle', activity: 'none' }
let burst: { mood: Mood; activity: Activity } | undefined // the last real work seen while a scene dwells
let settle: { cancel: () => void } | undefined
let timer: { cancel: () => void } | undefined
let terminalDrawnAt = -1000
const miniCache = new Map<string, string>()

// Runs `fn` after the hook returned, one task at a time, in the order the hooks queued them.
function defer($: EngineInterface, fn: () => Promise<unknown>): void {
  postQueue = postQueue.then(() => new Promise<void>(resolve => {
    $.clock.after(0, () => {
      fn().catch(() => undefined).finally(resolve)
    })
  }))
}

// Every profile and board write runs here, one at a time. Never call serial from inside serial.
function serial<T>(fn: () => Promise<T>): Promise<T> {
  const run = gameQueue.then(fn)
  gameQueue = run.catch(() => undefined)
  return run
}

// This project's stored profile as it is now (another session may have moved it). Inside serial only.
async function freshProfile($: EngineInterface): Promise<Profile> {
  if (!keys) return profileCache ?? newProfile()
  const raw: unknown = await $.store.get(keys.profile).catch(() => undefined)
  isFrozen = isNewerProfile(raw)
  const text = JSON.stringify(raw ?? null)
  if (profileCache && text === seenProfile) return profileCache
  seenProfile = text
  profileCache = migrateProfile(raw)
  return profileCache
}

// Shows a profile in this session (cache and atoms); writes nothing.
async function publishProfile($: EngineInterface, next: Profile): Promise<void> {
  const hatChanged = profileCache?.hat !== next.hat
  profileCache = next
  await update($, profileAtom, () => next)
  if (hatChanged) await update($, hatAtom, () => next.hat)
}

// Read-modify-write of this project's profile on the fresh stored value (another session may
// have moved it). Inside serial only. A save from a newer version is left alone: after === before.
async function changeProfile($: EngineInterface, fn: (p: Profile) => Profile): Promise<{ before: Profile; after: Profile }> {
  const shown = profileCache
  const before = await freshProfile($)
  if (isFrozen) {
    if (before !== shown) await publishProfile($, before)
    return { before, after: before }
  }
  const after = fn(before)
  await publishProfile($, after)
  if (keys) {
    await $.store.set(keys.profile, after).catch(() => undefined)
    seenProfile = JSON.stringify(after)
  }
  return { before, after }
}

// Outside serial only (pane, petting): never from a serial task, since setup awaits the queue.
async function loadProfile($: EngineInterface): Promise<Profile> {
  if (!isLoaded) await ensureQuick($)
  if (profileCache) return profileCache
  return serial(() => freshProfile($))
}

// The old global save goes to the first project that loads after the update, once; the old keys stay as a backup.
async function adoptLegacy($: EngineInterface, now: number): Promise<void> {
  if (!keys) return
  if ((await $.store.get(keys.profile).catch(() => undefined)) !== undefined) return
  if ((await $.store.get(CLAIM_KEY).catch(() => undefined)) !== undefined) return
  const old: unknown = await $.store.get(STORE_KEY).catch(() => undefined)
  if (old === undefined || old === null) return
  await $.store.set(CLAIM_KEY, { by: keys.id, at: now }).catch(() => undefined)
  const claim = await $.store.get(CLAIM_KEY).catch(() => undefined)
  if ((claim as { by?: string } | undefined)?.by !== keys.id) return // another session won it
  await $.store.set(keys.profile, isNewerProfile(old) ? old : migrateProfile(old)).catch(() => undefined)
  const hat = sanitizeHat(await $.store.get(HAT_KEY).catch(() => undefined))
  if (hat && (await $.store.get(keys.hat).catch(() => undefined)) === undefined) await $.store.set(keys.hat, hat).catch(() => undefined)
  const room = migrateDecor(await $.store.get(DECOR_KEY).catch(() => undefined))
  if (Object.keys(room).length > 0 && (await $.store.get(keys.decor).catch(() => undefined)) === undefined) {
    await $.store.set(keys.decor, room).catch(() => undefined)
  }
}

// Another session in this project folder may have earned xp, worn a hat or moved the decor:
// catch up. Writes atoms only when the stored JSON changed, so the scene does not redraw for nothing.
async function refreshLocked($: EngineInterface): Promise<void> {
  if (!keys) return
  const before = profileCache
  const p = await freshProfile($)
  if (p !== before) await publishProfile($, p)
  await freshBoard($)
  const hat = sanitizeHat(await $.store.get(keys.hat).catch(() => undefined))
  if (JSON.stringify(hat) !== JSON.stringify(await read($, customHat))) await update($, customHat, () => hat)
  const room = migrateDecor(await $.store.get(keys.decor).catch(() => undefined))
  if (JSON.stringify(room) !== JSON.stringify(await read($, decor))) await update($, decor, () => room)
}

function quipFor(mood: Mood, activity: Activity, file: string, ctx: { now: number; avoid?: string }): string {
  const d = new Date(ctx.now)
  const p = profileCache
  return pickQuip({
    mood, activity, tags, project, file,
    turns: turnCount,
    hour: d.getHours(), weekday: d.getDay(), month: d.getMonth() + 1, day: d.getDate(),
    combo: comboNow,
    errorsInRow,
    turnSeconds: turnStartedAt > 0 ? Math.round((ctx.now - turnStartedAt) / 1000) : 0,
    level: levelOf(p?.xp ?? 0).level,
    streak: p?.streak.count ?? 0,
    hat: p?.hat ?? null,
    avoid: ctx.avoid,
  })
}

type MoodChange = { mood: Mood; activity?: Activity; detail?: string; quip?: string; now: number }

// Shows a mood. Without an explicit quip a fresh line under the same mood is kept for a few
// seconds, and nothing is written when nothing changed. Answers the token of this change.
function isSameScene(a: { mood: Mood; activity: Activity }, b: { mood: Mood; activity: Activity }): boolean {
  return a.mood === b.mood && a.activity === b.activity
}

// Asks the room to show a mood. Shown at once when the current scene had its time;
// otherwise remembered, and the room catches up when the dwell is over.
function requestScene($: EngineInterface, mood: Mood, activity: Activity, now: number): void {
  latest = { mood, activity }
  if (!REST_MOODS.includes(mood)) burst = { mood, activity }
  const dwell = SCENE_DWELL[shown.mood] ?? SCENE_DWELL_MS
  const left = shown.at + dwell - now
  if (left <= 0) {
    settle?.cancel()
    settle = undefined
    void commitScene($, now)
    return
  }
  if (!settle) settle = $.clock.after(left, () => {
    settle = undefined
    void $.clock.now().then(t => commitScene($, t))
  })
}

// Shows what is due: the latest mood, except that work seen during the dwell gets its
// own scene before Clawd goes back to resting. Keeps catching up until it shows the latest.
async function commitScene($: EngineInterface, now: number): Promise<void> {
  const target = burst && REST_MOODS.includes(latest.mood) && !isSameScene(burst, shown) ? burst : latest
  burst = undefined
  if (!isSameScene(target, shown)) {
    // Start the next scene from where Clawd really is right now (mid-wander, mid-walk, on the stool).
    const first = shown.at === 0
    const here = clawdAt(stationOf(shown.mood, shown.activity), (now - shown.at) / 1000, shown.walk)
    const home = clawdAt(stationOf(target.mood, target.activity), 0)
    const from = { mood: shown.mood, activity: shown.activity }
    shown = { ...target, at: now, walk: first ? undefined : { dx: Math.round(here.x - home.x), dy: Math.round(here.y - home.y) } }
    await update($, sceneAtom, () => ({
      mood: target.mood, activity: target.activity, at: now,
      fromX: first ? null : here.x, fromY: first ? null : here.y,
      fromMood: first ? null : from.mood, fromActivity: first ? null : from.activity,
    }))
  }
  if (!isSameScene(latest, shown) && !settle) {
    const dwell = SCENE_DWELL[shown.mood] ?? SCENE_DWELL_MS
    settle = $.clock.after(dwell, () => {
      settle = undefined
      void $.clock.now().then(t => commitScene($, t))
    })
  }
}

async function setMood($: EngineInterface, change: MoodChange): Promise<number> {
  token += 1
  const mine = token
  const activity = change.activity ?? 'none'
  const detail = change.detail ?? ''
  const current = petNow ?? PET_START
  const sameScene = current.mood === change.mood && current.activity === activity
  const line = change.quip ??
    (sameScene && change.now - quipShownAt < QUIP_HOLD_MS ? current.quip : quipFor(change.mood, activity, detail, { now: change.now, avoid: current.quip }))
  if (sameScene && current.detail === detail && current.quip === line) return mine
  if (mine !== token) return mine
  const next: PetState = { mood: change.mood, activity, detail, quip: line }
  if (line !== current.quip) quipShownAt = change.now
  petNow = next
  requestScene($, change.mood, activity, change.now)
  await update($, pet, () => next)
  return mine
}

// Back to thinking while a turn runs, otherwise idle.
async function restMood($: EngineInterface): Promise<number> {
  const now = await $.clock.now()
  return setMood($, { mood: turnStartedAt > 0 ? 'thinking' : 'idle', now })
}

// After a tool: rest only once no other tool started for a moment, so quick runs of tools
// do not flicker through 'thinking'.
function restSoon($: EngineInterface): void {
  const mine = token
  $.clock.after(REST_DELAY_MS, () => {
    if (token === mine && activeTools === 0) void restMood($)
  })
}

function toast($: EngineInterface, text: string, timeoutMs = 4000): void {
  try {
    $.ui.toast(text, { timeoutMs })
  } catch {
    // a surface without toasts
  }
}

// ---------- toasts: one per queued pass, the most important item first ----------

const RANK = { level: 0, projectTrophy: 1, achievement: 2, campaign: 3, quest: 4, hat: 5, decor: 6 } as const
// `verb` and `what` are the note's line in the Room's Recent list; an empty verb only toasts.
export type Note = { rank: number; text: string; short: string; verb: string; what: string }

function announceDecor(notes: Note[], before: Profile, after: Profile): void {
  for (const item of newlyUnlocked(before, after)) {
    notes.push({ rank: RANK.decor, text: `New decor: ${item.name}. Rearrange the room in the Decor tab.`, short: `decor ${item.name}`, verb: 'New decor', what: item.name })
  }
}

// A short age for the Recent list: just now, 5m ago, 3h ago, 2d ago.
export function ago(ms: number): string {
  const m = Math.floor(ms / 60_000)
  if (m < 1) return 'just now'
  if (m < 60) return `${m}m ago`
  const h = Math.floor(m / 60)
  return h < 24 ? `${h}h ago` : `${Math.floor(h / 24)}d ago`
}

// Long enough to read: about 45 ms a character, never under 3.5 s or over 9 s.
const toastMs = (text: string) => Math.max(3500, Math.min(9000, 1500 + text.length * 45))

export function toastText(notes: Array<Pick<Note, 'rank' | 'text' | 'short'>>): { text: string; timeoutMs: number } | undefined {
  if (notes.length === 0) return undefined
  const [head, ...others] = [...notes].sort((a, b) => a.rank - b.rank)
  if (!head) return undefined
  const shown = others.slice(0, 2).map(n => n.short).join(', ')
  const also = others.length === 0 ? '' : `  ·  Also: ${shown}${others.length > 2 ? ` (+${others.length - 2} more)` : ''}`
  const text = head.text + also
  return { text, timeoutMs: toastMs(text) }
}

// Toasts the notes and keeps them in this project's Recent list (call only inside serial).
async function flushNotes($: EngineInterface, notes: Note[], now: number): Promise<void> {
  const t = toastText(notes)
  if (t) toast($, t.text, t.timeoutMs)
  const added = notes.filter(n => n.verb !== '').map(n => ({ verb: n.verb, what: n.what, at: now }))
  if (added.length === 0) return
  await changeProfile($, p => ({ ...p, recent: [...(p.recent ?? []), ...added].slice(-RECENT_SIZE) }))
}

// ---------- the game, the board and the wardrobe (all inside `serial`) ----------

// Applies one game event (call only inside serial), saves the profile, collects what to toast,
// and answers the line worth showing over Clawd, if any.
async function applyLocked($: EngineInterface, event: GameEvent, notes: Note[]): Promise<string | undefined> {
  const box: { result?: GameResult } = {}
  const { before } = await changeProfile($, p => (box.result = applyEvent(p, event)).profile)
  const result = box.result
  if (!result) return undefined // a newer version's save: nothing is paid
  if (result.xpGained > 0) await update($, stats, s => ({ ...s, xp: s.xp + result.xpGained }))
  announceDecor(notes, before, result.profile)

  let line: string | undefined
  for (const quest of result.completedQuests) {
    notes.push({ rank: RANK.quest, text: `Quest done: ${quest.title} (+${quest.xp} xp)`, short: quest.title, verb: 'Quest done', what: quest.title })
    line = questDoneQuip(quest.title)
  }
  if (sweepsOf(result.profile) > sweepsOf(before)) {
    notes.push({ rank: RANK.quest, text: `Every daily quest done! Claim the Daily Sweep (+${XP.sweep} xp) before midnight.`, short: 'Daily Sweep ready', verb: '', what: '' })
  }
  if (result.profile.sweepClaimed !== before.sweepClaimed && event.type === 'claim') {
    notes.push({ rank: RANK.quest, text: `Daily Sweep! Every daily quest done (+${XP.sweep} xp)`, short: 'Daily Sweep', verb: 'Daily Sweep', what: 'every daily quest done' })
    line = 'Daily Sweep! Every quest of the day, done.'
  }
  for (const achievement of result.unlocked) {
    notes.push({ rank: RANK.achievement, text: `Achievement unlocked: ${achievement.name}`, short: achievement.name, verb: 'Trophy', what: achievement.name })
    line = achievementQuip(achievement.name)
  }
  for (const hat of result.unlockedHats) {
    const name = HATS.find(item => item.id === hat)?.name ?? hat
    notes.push({ rank: RANK.hat, text: `New hat: ${name}. Try it on in the wardrobe.`, short: `hat ${name}`, verb: 'New hat', what: name })
  }
  if (result.levelUp !== null) {
    notes.push({ rank: RANK.level, text: `Level up! Clawd is now level ${result.levelUp}.`, short: `level ${result.levelUp}`, verb: 'Level up', what: `level ${result.levelUp}` })
    line = levelUpQuip(result.levelUp)
  }
  return line
}

function play($: EngineInterface, event: GameEvent): Promise<string | undefined> {
  return serial(async () => {
    const notes: Note[] = []
    const line = await applyLocked($, event, notes)
    await flushNotes($, notes, event.now)
    return line
  })
}

// The claim button: pays today's Daily Sweep through the queue (a second press finds nothing to pay).
async function claimSweep($: EngineInterface): Promise<void> {
  const now = await $.clock.now()
  const line = await play($, { type: 'claim', now })
  if (!line) return
  const mine = await setMood($, { mood: 'happy', quip: line, now })
  $.clock.after(3500, () => {
    if (token === mine && activeTools === 0) void restMood($)
  })
}

async function saveBoard($: EngineInterface, next: ProjectQuestBoard | null): Promise<void> {
  await update($, board, () => next)
  if (project === '' || !keys) return
  if (next) await $.store.set(keys.board, next).catch(() => undefined)
  else await $.store.delete(keys.board).catch(() => undefined)
  seenBoard = JSON.stringify(next ?? null)
}

// This project's board as stored now (another session may have moved it). Inside serial only.
async function freshBoard($: EngineInterface): Promise<ProjectQuestBoard | null> {
  if (!keys || project === '') return read($, board)
  const raw: unknown = await $.store.get(keys.board).catch(() => undefined)
  const text = JSON.stringify(raw ?? null)
  if (text !== seenBoard) {
    seenBoard = text
    await update($, board, () => migrateBoard(raw))
  }
  return read($, board)
}

// Counts a tool call or a turn toward the project quests and pays what finished, all in one pass
// of the queue (the board is read inside it, so parallel tools never pay twice).
function progressBoard($: EngineInterface, now: number, compute: (b: ProjectQuestBoard) => Progress): Promise<string | undefined> {
  if (project === '') return Promise.resolve(undefined)
  return serial(async () => {
    const before = await freshBoard($)
    if (!before) return undefined
    const progress = compute(before)
    if (!progress.changed) return undefined
    await saveBoard($, progress.board)

    const notes: Note[] = []
    let line: string | undefined
    let total = 0
    for (const quest of progress.finished) {
      notes.push({ rank: RANK.quest, text: `Project quest done: ${quest.title} (+${quest.xp} xp)`, short: quest.title, verb: 'Quest done', what: quest.title })
      total += quest.xp
      line = questDoneQuip(quest.title)
    }
    if (progress.campaignDone) {
      notes.push({ rank: RANK.campaign, text: `Campaign complete: ${progress.board.campaign}! (+${CAMPAIGN_BONUS_XP} xp)`, short: `campaign ${progress.board.campaign}`, verb: 'Campaign done', what: progress.board.campaign })
      total += CAMPAIGN_BONUS_XP
      line = `${progress.board.campaign}: complete. Legendary.`
    }
    for (const milestone of progress.milestones) {
      notes.push({ rank: RANK.projectTrophy, text: `Project trophy unlocked: ${milestone.name} (+${milestone.xp} xp)`, short: milestone.name, verb: 'Trophy', what: milestone.name })
      total += milestone.xp
      line = achievementQuip(milestone.name)
    }
    for (const hat of progress.hats) {
      notes.push({ rank: RANK.hat, text: `New project hat: ${hat.name}. Try it on in the wardrobe.`, short: `hat ${hat.name}`, verb: 'New hat', what: hat.name })
    }
    if (total > 0) line = (await applyLocked($, { type: 'bonus', xp: total, now }, notes)) ?? line
    await flushNotes($, notes, now)
    return line
  })
}

async function wearLocked($: EngineInterface, hat: HatId | null, now: number): Promise<void> {
  const { after } = await changeProfile($, p => equipHat(p, hat, now))
  await update($, hatAtom, () => after.hat)
  await update($, customHat, () => null)
  if (keys) await $.store.delete(keys.hat).catch(() => undefined)
}

function wear($: EngineInterface, hat: HatId | null): Promise<void> {
  return serial(async () => wearLocked($, hat, await $.clock.now()))
}

async function wearCustom($: EngineInterface, hat: CustomHat): Promise<void> {
  const now = await $.clock.now()
  await serial(async () => {
    await wearLocked($, null, now)
    await update($, customHat, () => hat)
    if (keys) await $.store.set(keys.hat, hat).catch(() => undefined)
  })
  await setMood($, { mood: 'happy', quip: `${hat.name}. Custom made for ${project || 'this project'}.`, now })
}

async function setDecor($: EngineInterface, slot: DecorSlot, id: string): Promise<void> {
  await serial(async () => {
    if (!keys) return
    const room = { ...migrateDecor(await $.store.get(keys.decor).catch(() => undefined)), [slot]: id }
    await update($, decor, () => room)
    await $.store.set(keys.decor, room).catch(() => undefined)
  })
  const item = DECOR.find(d => d.slot === slot && d.id === id)
  if (item && id !== 'none') await setMood($, { mood: 'happy', quip: `${item.name}. Nice touch.`, now: await $.clock.now() })
}

// ---------- session bookkeeping (survives a hot reload) ----------

async function loadBoard($: EngineInterface): Promise<void> {
  if (project === '') {
    await update($, board, () => null)
    return
  }
  if (!keys) return
  const key = keys.board
  let raw: unknown = await $.store.get(key).catch(() => undefined)
  if (raw === undefined || raw === null) {
    const legacy = storeKey(project)
    if (legacy !== key) {
      const old: unknown = await $.store.get(legacy).catch(() => undefined)
      if (old !== undefined && old !== null) {
        raw = old
        await $.store.set(key, old).catch(() => undefined)
        await $.store.delete(legacy).catch(() => undefined)
      }
    }
  }
  seenBoard = JSON.stringify(raw ?? null)
  await update($, board, () => migrateBoard(raw))
}

function isStale(gen: QuestGen, now: number): boolean {
  return gen.status === 'working' && (gen.startedAt === undefined || now - gen.startedAt > GEN_STALE_MS)
}

async function setup($: EngineInterface): Promise<void> {
  if (petNow === undefined) petNow = await read($, pet)
  if (!isLoaded) {
    const now = await $.clock.now()
    cwdNow = await $.session.cwd().catch(() => '')
    const folder = cwdNow.split(/[\\/]/).filter(Boolean).pop() ?? ''
    project = normProject(folder)
    keys = projectKeys(project, cwdNow)
    seenProfile = ''
    seenBoard = ''
    isFrozen = false
    tags = new Set([...tagsFromPath(folder), ...tagsFromEntries((await $.fs.list().catch(() => [])).map(entry => entry.name))])
    turnCount = await $.session.turns().catch(() => 0)
    comboNow = await read($, combo)
    if (lastActiveAt === 0) lastActiveAt = now
    if (lastToolAt === 0 && comboNow > 0) lastToolAt = now
    await serial(() => adoptLegacy($, now))
    await serial(() => loadBoard($))
    await update($, questGen, (g): QuestGen => (isStale(g, now) ? { status: 'idle', message: '' } : g))
    const limits = migrateLimits(await $.store.get(LIMITS_KEY).catch(() => undefined))
    const live = await $.session.usage().catch(() => undefined)
    await update($, usageAtom, u => {
      const seeded = seedUsage(u, limits, live, now)
      limitsSeeded = !live?.rateLimits?.length && (seeded.fiveHour !== u.fiveHour || seeded.sevenDay !== u.sevenDay)
      return seeded
    })
    isLoaded = true
  }
  if (timer === undefined) startTimer($)
}

// Idempotent: loads what the module lost in a reload (project, board, ticker).
function ensureSession($: EngineInterface): Promise<void> {
  if (isLoaded && timer !== undefined && petNow !== undefined) return Promise.resolve()
  ensuring ??= setup($).finally(() => {
    ensuring = undefined
  })
  return ensuring
}

// Awaits the setup only when the project is not known yet; otherwise lets it run on its own.
async function ensureQuick($: EngineInterface): Promise<void> {
  if (!isLoaded) await ensureSession($).catch(() => undefined)
  else void ensureSession($).catch(() => undefined)
}

// The scene frame reloads whenever its source changes, so the source only changes when the
// drawing does: the same scene keeps its phased source, and a new one is phased to resume its
// animations from where they are now (scene time for Clawd, wall time for the room).
let sceneCache = { key: '', svg: '' }
// The usage meters' one-shot changes run on their own clock (meterAt: when a drawn step last changed).
function phasedScene(svg: string, sceneAt: number, now: number, meterAt = 0): string {
  if (sceneCache.key !== svg) {
    const sceneSecs = sceneAt > 0 ? (now - sceneAt) / 1000 : 0
    const meterSecs = meterAt > 0 ? Math.round((now - meterAt) / 10) / 100 : 3600
    sceneCache = { key: svg, svg: phaseSvg(svg, Math.round(sceneSecs * 100) / 100, Math.round((now / 1000) % 3600 * 100) / 100, meterSecs) }
  }
  return sceneCache.svg
}

function startTimer($: EngineInterface): void {
  timer?.cancel()
  timer = $.clock.every(220, () => {
    void onTick($).catch(() => undefined)
  })
}

// Mini Clawds: Agent calls still in flight, or subagents the engine lists as running. A background
// agent's (or a workflow's) tool call returns at once, so only the list sees it working on.
// A workflow's agents are in no list: each one counts while its tool calls keep coming.
let agentCalls = 0
let runningAgents = 0
const seenAgents = new Map<string, number>()
const AGENT_QUIET_MS = 90_000
async function syncHelpers($: EngineInterface, refresh = false): Promise<void> {
  if (refresh) {
    const list = await $.agent.list().catch(() => undefined)
    if (list) runningAgents = list.filter(a => a.status === 'running').length
    const now = await $.clock.now()
    for (const [id, at] of seenAgents) if (now - at > AGENT_QUIET_MS) seenAgents.delete(id)
  }
  const count = Math.min(3, Math.max(agentCalls, runningAgents, seenAgents.size))
  if ((await read($, helpers)) !== count) await update($, helpers, () => count)
}

async function onTick($: EngineInterface): Promise<void> {
  tick += 1
  if (tick % 5 === 0) await syncHelpers($, true)
  if (tick % 23 === 0 && isLoaded) void serial(() => refreshLocked($)).catch(() => undefined) // about every 5 s
  const state = petNow
  if (!state) return
  // The terminal sprite steps at the mood's pace: a calm sleep, a bouncy hop, a busy Clawd every tick.
  // Idle only blinks: tick%16 === 0 lands on an odd frame (eyes shut), the next tick on an even one.
  const step = state.mood === 'idle' ? 0 : state.mood === 'sleeping' ? 8 : (state.mood === 'happy' || state.mood === 'done') ? 2 : 1
  if (tick - terminalDrawnAt < 20 && (step === 0 ? tick % 16 < 2 : tick % step === 0)) {
    await update($, frame, n => (state.mood !== 'idle' ? n + 1 : tick % 16 === 0 ? (n % 2 === 0 ? n + 1 : n + 2) : (n % 2 === 1 ? n + 1 : n + 2)))
  }

  if (tick % 20 === 0 && state.mood === 'idle' && activeTools === 0) {
    const now = await $.clock.now()
    if (now - lastActiveAt > SLEEP_AFTER_MS) await setMood($, { mood: 'sleeping', now })
  }

  const every = state.mood === 'idle' || state.mood === 'sleeping' ? 70 : 30
  if (tick % every === 0 && state.mood !== 'happy') {
    const now = await $.clock.now()
    const quip = quipFor(state.mood, state.activity, state.detail, { now, avoid: state.quip })
    const next = await update($, pet, current => (current.mood === state.mood && current.quip === state.quip ? { ...current, quip } : current))
    if (petNow === state) {
      petNow = next
      if (next.quip === quip) quipShownAt = now
    }
  }
}

function mini(mood: Mood, activity: Activity, hat: AnyHat): string {
  // A custom hat is keyed by its art too: a regenerated project hat can reuse an id.
  const hatKey = hat === null ? 'none' : typeof hat === 'string' ? hat : `custom:${hat.id}:${hat.rows.join('/')}:${JSON.stringify(hat.palette)}`
  const key = `${mood}|${activity}|${hatKey}`
  let svg = miniCache.get(key)
  if (svg === undefined) {
    if (miniCache.size > 300) miniCache.clear()
    svg = miniSvg({ mood, activity, hat })
    miniCache.set(key, svg)
  }
  return svg
}

// ---------- /quests ----------

const TREE_MAX = 400
const READ_MAX = 256 * 1024

const sortedList = async ($: EngineInterface, dir: string) =>
  [...(await $.fs.list(dir === '' ? undefined : dir.replace(/\/$/, '')).catch(() => []))].sort((a, b) => a.name.localeCompare(b.name))

// The project's paths (dirs end with '/'), breadth first: no .git, no ignored, secret or binary paths.
async function scanTree($: EngineInterface, depth = 3): Promise<string[]> {
  const out: string[] = []
  let level = ['']
  let lists = 0
  for (let d = 0; d < depth && level.length > 0 && out.length < TREE_MAX; d++) {
    const next: string[] = []
    for (const dir of level) {
      if (++lists > 80) break
      for (const entry of await sortedList($, dir)) {
        const rel = `${dir}${entry.name}${entry.kind === 'dir' ? '/' : ''}`
        if (out.length >= TREE_MAX || entry.kind === 'other' || entry.name === '.git' || isIgnored(rel)) continue
        out.push(rel)
        if (entry.kind === 'dir') next.push(rel)
      }
    }
    level = next
  }
  return out
}

// Text files under a folder ('' = the project) that `keep` wants, read-only; secrets and binaries never read.
// Only wanted files count toward the cap.
async function filesUnder($: EngineInterface, dir: string, keep: (rel: string) => boolean): Promise<ProbeFile[]> {
  const out: ProbeFile[] = []
  let level = [dir]
  let lists = 0
  for (let d = 0; d < 4 && level.length > 0 && out.length < PROBE_FILES; d++) {
    const next: string[] = []
    for (const at of level) {
      if (++lists > 60) break
      for (const entry of await sortedList($, at)) {
        const rel = `${at}${entry.name}${entry.kind === 'dir' ? '/' : ''}`
        if (entry.kind === 'other' || entry.name === '.git' || isIgnored(rel)) continue
        if (entry.kind === 'dir') next.push(rel)
        else if (out.length < PROBE_FILES && entry.size <= READ_MAX && keep(rel)) out.push({ path: rel, text: String(await $.fs.read(rel).catch(() => '')) })
      }
    }
    level = next
  }
  return out
}

// What each due probe measures: its file, its folder or its '.ext' files; vanished when the target is gone.
async function readProbes($: EngineInterface, due: ProbeDue[]): Promise<ProbeRead[]> {
  const reads: ProbeRead[] = []
  for (const { id, check } of due) {
    const path = check.path
    // more-files reads only names with its ending, so other files never fill the cap
    const ending = check.probe === 'more-files' ? check.pattern.toLowerCase() : ''
    if (path.endsWith('/')) {
      const isThere = await $.fs.exists(path.replace(/\/$/, '')).catch(() => false)
      reads.push(isThere ? { id, files: await filesUnder($, path, rel => matchesPath(path, rel) && rel.toLowerCase().endsWith(ending)) } : { id, vanished: true })
    } else if (path.startsWith('.') && !path.includes('/')) {
      reads.push({ id, files: await filesUnder($, '', rel => matchesPath(path, rel)) })
    } else {
      const stat = await $.fs.stat(path).catch(() => undefined)
      if (!stat) reads.push({ id, vanished: true })
      else if (isOffLimits(path) || stat.size > READ_MAX) reads.push({ id, files: [] })
      else reads.push({ id, files: [{ path, text: String(await $.fs.read(path).catch(() => '')) }] })
    }
  }
  return reads
}

// End of a turn that changed files: measured quests are read once, vanished targets rerolled.
async function refreshProbes($: EngineInterface, turnStart: number, now: number): Promise<string | undefined> {
  if (project === '') return undefined
  const current = await serial(() => freshBoard($))
  if (!current) return undefined
  const due = probesDue(current, turnStart)
  const reads = await readProbes($, due)
  for (const t of tallyTargets(current)) {
    if (!(await $.fs.exists(t.path.replace(/\/$/, '')).catch(() => true))) reads.push({ id: t.id, vanished: true })
  }
  if (reads.length === 0) return undefined
  const spare = reads.some(r => 'vanished' in r) || due.some(d => d.check.at === -1) ? templates(await scanTree($), [...tags]) : []
  // The reads were taken outside the queue: drop them if /quests replaced the campaign meanwhile.
  return progressBoard($, now, b => applyProbes(b, b.createdAt === current.createdAt ? reads : [], now, spare))
}

async function generateQuests($: EngineInterface, focus: string): Promise<void> {
  const now = await $.clock.now()
  const message = `Clawd is scouting ${project || 'the project'} for quests...`
  let claimed = false
  await update($, questGen, (g): QuestGen => {
    claimed = g.status !== 'working' || isStale(g, now)
    return claimed ? { status: 'working', message, startedAt: now } : g
  })
  if (!claimed) return

  const gate = canRegenerate(await read($, board), now)
  if (!gate.ok) {
    // the Quests tab says when new ones unlock; nothing failed
    await update($, questGen, () => ({ status: 'idle', message: '' }))
    return
  }

  let mine = await setMood($, { mood: 'reading', activity: 'search', detail: project, quip: 'Scouting the project for quests...', now })
  try {
    const tree = await scanTree($)
    const readmeName = tree.find(name => /^readme(\.md|\.txt|\.rst)?$/i.test(name))
    const readme = readmeName ? String(await $.fs.read(readmeName).catch(() => '')).slice(0, 1500) : ''
    const current = await read($, board)
    const prompt = buildPrompt({
      project,
      tags: [...tags],
      tree,
      readme,
      recentPrompts: await read($, recentPromptsAtom),
      recentWork: (await read($, log)).map(entry => `${entry.verb} ${entry.what}`),
      focus,
      needMilestones: !current || current.milestones.length === 0 || current.milestones.every(m => m.done),
    })
    const ask = (text: string) => $.model.complete({ model: 'sonnet', system: SYSTEM, prompt: text, maxTokens: 3000, timeoutMs: GEN_TIMEOUT_MS })
    const reply = await ask(prompt)
    if (!reply.isAnswered) throw new Error(`no answer (${reply.reason})`)
    const ctx = { tree, project, readme }
    let parsed = parseCandidates(reply.text, tree)
    // too few good candidates: one repair ask with the reasons; templates fill whatever is still missing
    if (parsed.quests.filter(c => validateCandidate(c, ctx) === null).length < 4) {
      const again = await ask(repairPrompt(prompt, rejections(parsed, ctx))).catch(() => undefined)
      if (again?.isAnswered) parsed = mergeParsed(parsed, parseCandidates(again.text, tree))
    }
    const spare = templates(tree, [...tags])
    const start = await $.clock.now()
    let fresh = buildBoard(parsed, ctx, spare, current, start)
    // measured quests start from how the files are now
    fresh = applyProbes(fresh, await readProbes($, probesDue(fresh, Number.POSITIVE_INFINITY)), start, spare).board
    const created = await serial(async () => {
      const merged = mergeBoard(fresh, await freshBoard($))
      await saveBoard($, merged)
      return merged
    })
    await update($, questGen, () => ({ status: 'idle', message: '' }))
    const news = `New campaign: ${created.campaign} (${created.items.length} quests)`
    toast($, news, toastMs(news))
    mine = await setMood($, { mood: 'happy', quip: `New campaign: ${created.campaign}. Let us go.`, now: await $.clock.now() })
  } catch (err) {
    const reason = err instanceof Error ? err.message : String(err)
    await update($, questGen, () => ({ status: 'error', message: `The quest scroll caught fire. Press the button to try again. (${reason.slice(0, 80)})` }))
    if (token === mine) mine = await setMood($, { mood: 'error', quip: 'The quest scroll caught fire. Try again?', now: await $.clock.now() })
  }
  $.clock.after(5000, () => {
    if (token === mine && activeTools === 0) void restMood($)
  })
}

const TABS: Array<{ id: Tab; label: string }> = [
  { id: 'room', label: 'Room' },
  { id: 'quests', label: 'Quests' },
  { id: 'trophies', label: 'Trophies' },
  { id: 'wardrobe', label: 'Wardrobe' },
  { id: 'decor', label: 'Decor' },
]

// What finished tool work the queue applies after the tool result went back to the model.
type ToolDone = {
  tool: string; activity: Activity; mood: Mood; detail: string; ext: string | null
  path: string; command: string; added: string; removed: string // for project quests: relative path, the command, an edit's new and replaced text
  isError: boolean; mine: number; count: number; turnStart: number
}

async function afterTool($: EngineInterface, t: ToolDone): Promise<void> {
  const now = await $.clock.now()
  const isFlowBroken = now - lastToolAt > FLOW_GAP_MS
  lastToolAt = now
  const streak = await update($, combo, n => (t.isError ? 0 : (isFlowBroken ? 0 : n) + 1))
  comboNow = streak
  if (t.count % 12 === 0) await update($, coffee, n => Math.max(0, n - 1))
  await update($, log, list => [...list, { verb: VERBS[t.activity], what: t.detail, isError: t.isError }].slice(-LOG_SIZE))
  await update($, stats, s => ({
    ...s,
    tools: s.tools + 1,
    edits: s.edits + (t.mood === 'coding' ? 1 : 0),
    reads: s.reads + (t.mood === 'reading' ? 1 : 0),
    runs: s.runs + (t.mood === 'running' ? 1 : 0),
    errors: s.errors + (t.isError ? 1 : 0),
  }))
  let announced = await play($, { type: 'tool', tool: t.tool, activity: t.activity, isError: t.isError, ext: t.ext, combo: streak, now })
  const ev = { activity: t.activity, path: t.path, command: t.command, added: t.added, removed: t.removed, isError: t.isError, turnStart: t.turnStart, now }
  announced = (await progressBoard($, now, b => onTool(b, ev))) ?? announced

  if (t.isError) {
    const mine = await setMood($, { mood: 'error', activity: t.activity, detail: t.detail, now })
    $.clock.after(2200, () => {
      if (token === mine && activeTools === 0) void restMood($)
    })
  } else if (announced) {
    const mine = await setMood($, { mood: 'happy', activity: t.activity, detail: t.detail, quip: announced, now })
    $.clock.after(3000, () => {
      if (token === mine && activeTools === 0) void restMood($)
    })
  } else if (activeTools === 0 && token === t.mine) {
    restSoon($)
  }
}

// A usage threshold or a compaction: one line from Clawd, no toast. A sleeping Clawd only wakes for a compaction.
async function usageReact($: EngineInterface, kind: UsageNote, mood?: Mood): Promise<void> {
  const now = await $.clock.now()
  if (now < lineHoldUntil) {
    usagePending = { kind, mood }
    return
  }
  const cur = petNow ?? PET_START
  if (cur.mood === 'sleeping' && kind !== 'compact') return
  usageShown = { kind, mood, at: now }
  const mine = await setMood($, { mood: mood ?? cur.mood, activity: cur.activity, detail: cur.detail, quip: usageQuip(kind), now })
  $.clock.after(QUIP_HOLD_MS, () => {
    if (token === mine && activeTools === 0) void restMood($)
  })
}

// ---------- hooks ----------

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'pet', description: 'Open or close the Clawd mascot pane' })
    await $.command.register({ name: 'quests', description: 'Clawd invents side quests for this project (optional: a focus, clear, reset, or allow <script>)' })
    isLoaded = false
    project = ''
    profileCache = undefined
    keys = undefined
    seenProfile = ''
    seenBoard = ''
    isFrozen = false
    lineHoldUntil = 0
    usageShown = undefined
    usagePending = undefined
    timer?.cancel()
    timer = undefined
    await update($, board, () => null)
    await update($, usageAtom, () => USAGE_START)
    await ensureSession($)
    const now = await $.clock.now()
    lastActiveAt = now

    const k = keys as ProjectKeys | undefined // set again by the setup above
    const worn = k ? sanitizeHat(await $.store.get(k.hat).catch(() => undefined)) : null
    const room = k ? migrateDecor(await $.store.get(k.decor).catch(() => undefined)) : {}
    await update($, decor, () => room)
    await update($, customHat, () => worn)

    await update($, profileAtom, () => null)
    const greeting = await play($, { type: 'session', project, now })
    await update($, hatAtom, () => profileCache?.hat ?? null)
    if (greeting) await setMood($, { mood: 'happy', quip: greeting, now })

    if (!(await read($, isHidden))) void $.ui.open({ id: PANE, title: 'Clawd' })
    return next(e)
  })

  on('command.run', { command: 'pet' }, async $ => {
    await ensureSession($).catch(() => undefined)
    const isUp = (await $.ui.panes()).some(pane => pane.id === PANE)
    if (isUp) {
      await $.ui.close({ id: PANE })
      await update($, isHidden, () => true)
      return { text: 'Clawd went for a walk.' }
    }
    await update($, isHidden, () => false)
    await $.ui.open({ id: PANE, title: 'Clawd' })
    return { text: 'Clawd is back.' }
  })

  on('command.run', { command: 'quests' }, async ($, e) => {
    await ensureSession($).catch(() => undefined)
    const args = e.args.trim()
    if (args === 'clear') {
      const kept = await serial(async () => {
        const current = await freshBoard($)
        if (!current) return false
        await saveBoard($, { ...current, items: [], isComplete: true })
        return true
      })
      return { text: kept ? 'Project quests cleared. Project trophies and hats stay.' : 'No project quests to clear.' }
    }
    if (args === 'allow' || args.startsWith('allow ')) {
      const cmd = scriptCommand(args.slice(5))
      if (!cmd) return { text: 'Clawd only counts a plain repo script this way, like /quests allow npm test or /quests allow make check.' }
      const done = await serial(async () => {
        const current = await freshBoard($)
        if (!current) return false
        await saveBoard($, { ...current, approved: [...(current.approved ?? []).filter(a => a !== cmd), cmd].slice(-10) })
        return true
      })
      return { text: done ? `Clawd counts \`${cmd}\` as a check now.` : 'No project quests yet. Run /quests first.' }
    }
    if (args === 'reset') {
      await serial(() => saveBoard($, null))
      return { text: 'Project quests reset. Project trophies and hats for this project are wiped.' }
    }
    await update($, isHidden, () => false)
    await update($, tab, () => 'quests')
    void $.ui.open({ id: PANE, title: 'Clawd' })
    const gate = canRegenerate(await read($, board), await $.clock.now())
    if (!gate.ok) return { text: `${gate.reason} (/quests clear drops the current quests.)` }
    void generateQuests($, args)
    return { text: `Clawd is scouting ${project || 'this project'} for quests${args ? ` about "${args}"` : ''}. Watch the Quests tab.` }
  })

  on('prompt.submit', async ($, e, next) => {
    await ensureQuick($)
    const now = await $.clock.now()
    lastActiveAt = now
    const isNewTurn = e.turnId === undefined
    if (isNewTurn) {
      activeTools = 0
      turnStartedAt = now
      turnTools = 0
      turnErrors = 0
    }
    // Only the person's own prompts react and count. A same-user socket (which the desktop app may
    // use) arrives unstamped as 'unclassified', so that one counts as the person's too.
    const kind = e.origin.kind
    if (kind !== 'composer' && kind !== 'bridge' && kind !== 'sdk' && kind !== 'unclassified') {
      if (isNewTurn) defer($, () => setMood($, { mood: 'thinking', now }))
      return next(e)
    }

    const text = e.text
    const trimmed = text.trim()
    if (trimmed !== '' && !trimmed.startsWith('/')) void update($, recentPromptsAtom, list => [...list, trimmed.slice(0, 200)].slice(-6))
    const reaction = promptReaction(text)
    defer($, async () => {
      const announced = await play($, { type: 'prompt', text, now })
      const line = announced ?? reaction
      if (line) {
        const mine = await setMood($, { mood: 'happy', quip: line, now })
        $.clock.after(3500, () => {
          if (token === mine) void restMood($)
        })
      } else if (isNewTurn) {
        await setMood($, { mood: 'thinking', now })
      }
    })
    return next(e)
  })

  on('tool.call', async ($, e, next) => {
    await ensureQuick($)
    const now = await $.clock.now()
    const args = e as ToolArgs
    const path = pathOf(args)
    const activity = activityFor(e.tool, args)
    const mood = moodFor(activity)
    const detail = detailFor(e.tool, args)

    // A subagent's tool (a workflow's too): a mini Clawd works on it, the main Clawd stays as he
    // is (asleep, even) and nothing counts. Only this chat's own work moves the main Clawd.
    if (e.agentId !== undefined) {
      seenAgents.set(e.agentId, now)
      void syncHelpers($)
      return next(e)
    }

    for (const tag of [...(path ? tagsFromPath(path) : []), ...(args.command ? tagsFromCommand(args.command) : [])]) tags.add(tag)
    if ((e.tool as string) === 'PowerShell') tags.add('powershell')
    activeTools += 1
    lastActiveAt = now
    if (activity === 'agent') {
      agentCalls += 1
      void syncHelpers($)
    }
    void setMood($, { mood, activity, detail, now })

    let result: Awaited<ReturnType<typeof next>>
    try {
      result = await next(e)
    } finally {
      activeTools = Math.max(0, activeTools - 1)
      if (activity === 'agent') {
        agentCalls = Math.max(0, agentCalls - 1)
        void syncHelpers($)
      }
    }

    const isError = result.deny !== undefined || result.isError === true
    turnTools += 1
    if (isError) {
      turnErrors += 1
      errorsInRow += 1
    } else {
      errorsInRow = 0
    }
    const done: ToolDone = {
      tool: e.tool, activity, mood, detail, ext: extOf(path),
      // a refused command never ran: no command, so it is neither red nor green for the quests
      path: path ? relativePath(path, cwdNow) : '', command: result.deny !== undefined ? '' : args.command ?? '', added: addedText(args), removed: removedText(args),
      isError, mine: token, count: turnTools, turnStart: turnStartedAt || now,
    }
    defer($, () => afterTool($, done))
    return result
  })

  on('turn.complete', async ($, e, next) => {
    if (e.agentId) {
      if (seenAgents.delete(e.agentId)) void syncHelpers($)
      return next(e)
    }
    await ensureQuick($)
    const now = await $.clock.now()
    const toolCount = turnTools
    const errors = turnErrors
    const durationMs = turnStartedAt > 0 ? now - turnStartedAt : 0
    const turnStart = turnStartedAt || now
    turnStartedAt = 0
    lastActiveAt = now
    turnCount += 1
    const reason = e.reason
    defer($, async () => {
      await update($, stats, s => ({ ...s, turns: s.turns + 1 }))
      if (reason === 'aborted' || reason === 'refusal') {
        await setMood($, { mood: 'idle', now })
        return
      }
      await update($, coffee, () => 3)
      const errorCount = errors + (reason === 'error' ? 1 : 0)
      let announced = await play($, { type: 'turn', durationMs, toolCount, errorCount, now })
      // every finished turn: the person may have written in their own editor (probesDue reads each at most once a turn)
      announced = (await refreshProbes($, turnStart, now)) ?? announced
      const mine = await setMood($, { mood: reason === 'error' ? 'error' : 'done', quip: announced, now })
      // a usage line shown just before this one comes back once it ends; one arriving meanwhile waits
      lineHoldUntil = now + TURN_LINE_MS
      if (usageShown && now - usageShown.at < QUIP_HOLD_MS) usagePending ??= usageShown
      usageShown = undefined
      $.clock.after(TURN_LINE_MS, () => {
        const p = usagePending
        usagePending = undefined
        if (p) void usageReact($, p.kind, p.mood)
        else if (token === mine) void restMood($)
      })
    })
    return next(e)
  })

  // Usage meters: the engine measures after each main-thread turn and when a limit moves a point.
  on('session.measure', async ($, e, next) => {
    await ensureQuick($)
    const now = await $.clock.now()
    let prev = await read($, usageAtom)
    if (limitsSeeded) {
      // stored limits stay only if this session has limits of its own (an API-key login has none)
      limitsSeeded = false
      if (!e.changed.includes('rateLimits') && !e.rateLimits?.length) prev = { ...prev, fiveHour: null, sevenDay: null }
    }
    const measured = measureUsage(prev, e, now)
    const { kind, warned } = usageNote(measured)
    await update($, usageAtom, () => ({ ...measured, warned }))
    if (e.changed.includes('rateLimits') || kind) {
      void $.store.set(LIMITS_KEY, { v: 1, fiveHour: measured.fiveHour, sevenDay: measured.sevenDay, warned: { fiveHour: warned.fiveHour, sevenDay: warned.sevenDay } }).catch(() => undefined)
    }
    if (kind) defer($, () => usageReact($, kind))
    return next(e)
  })

  // A compaction of the main conversation that went through: the papers go into the archive box.
  on('session.compact', async ($, e, next) => {
    const result = await next(e)
    if (e.agentId === undefined && e.trigger !== 'precompute' && result.skip === undefined) {
      await ensureQuick($)
      const now = await $.clock.now()
      await update($, usageAtom, u => compactUsage(u, now))
      defer($, () => usageReact($, 'compact', 'happy'))
    }
    return result
  })

  // The loading row: our own verb, and on the desktop a tiny Clawd in front of the engine's line.
  on('ui.render', { component: 'Spinner' }, async ($, e, next) => {
    // The verb follows the scene the mini Clawd shows (it dwells), and holds a moment so a quick
    // run of tools does not flick through five verbs.
    const shownScene = await read($, sceneAtom)
    const key = `${shownScene.mood}:${shownScene.activity}`
    const now = await $.clock.now()
    if (verbCache.key !== key && now - verbCache.at > 2500) {
      verbCache = { key, at: now, verb: spinnerVerb({ mood: shownScene.mood, activity: shownScene.activity, tags }) }
    }
    const rewritten = { ...e, props: { ...e.props, word: verbCache.verb } }

    if (e.surface !== 'desktop') return next(rewritten)
    const worn = await read($, customHat)
    const hat: AnyHat = worn ?? (await read($, hatAtom))
    const { Box, Svg } = $.ui.resolve(e)
    return (
      <Box flexDirection="row" alignItems="center" gap={1}>
        <Svg key="mini" source={mini(shownScene.mood, shownScene.activity, hat)} alt={`Clawd, ${shownScene.mood}`} width={40} height={25} isInteractive />
        {await next(rewritten)}
      </Box>
    )
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e, next) => {
    const { mood, activity, detail, quip } = await read($, pet)
    const p = (await read($, profileAtom)) ?? (await loadProfile($))
    const current = await read($, tab)
    const comboCount = await read($, combo)
    const projectBoard = await read($, board)
    const wornCustom = await read($, customHat)
    const now = await $.clock.now()
    const color = mood === 'error' ? RED : ORANGE
    const { level, from, to } = levelOf(p.xp)
    const xpText = `${p.xp - from}/${to - from}`
    const unlockedCount = Object.keys(p.achievements).filter(id => ACHIEVEMENTS.some(a => a.id === id)).length
    const cols = e.props.bodyColumns ?? 40
    // Full-width lines (the level bar, the section rules) stop a cell short, so they never wrap or truncate.
    const fullW = Math.max(8, cols - 1)

    if (e.surface === 'terminal') {
      terminalDrawnAt = tick
      const { Box, Text, Button } = $.ui.resolve(e)
      const f = await read($, frame)
      // A narrow pane drops the hat name.
      const worn = cols >= 48 ? hatName(p.hat, wornCustom) : ''
      const group = (title: string, items: Quest[]) => {
        const open = items.filter(q => !q.done)
        const shown = open.slice(0, 3)
        const w = Math.max(0, ...shown.map(q => amount(q).length))
        return (
          <Box flexDirection="column">
            <Text dimColor wrap="truncate-end">{title}</Text>
            {items.length > 0 && open.length === 0 && (
              <Text>
                <Text color={GREEN}>{'  ✓ '}</Text>
                <Text dimColor>all done</Text>
              </Text>
            )}
            {shown.map(q => (
              <Text wrap="truncate-end">
                <Text color={ORANGE}>{'[ ] '}</Text>
                <Text dimColor>{amount(q).padEnd(w)}</Text>
                <Text> {q.title}</Text>
                <Text dimColor>  +{q.xp} xp</Text>
              </Text>
            ))}
            {open.length > 3 && <Text dimColor>  +{open.length - 3} more</Text>}
          </Box>
        )
      }
      return (
        <Box flexDirection="column">
          <Box flexDirection="column" alignItems="center">
            {petAscii(mood, f).map(line => <Text color={color}>{line}</Text>)}
            <Text bold color={color}>{quip}</Text>
            {detail !== '' ? <Text dimColor wrap="truncate-end">{detail}</Text> : <Text> </Text>}
          </Box>
          <Text> </Text>
          <Text wrap="truncate-end">
            <Text bold color={ORANGE}>Lv {level}</Text>
            <Text dimColor>  {xpText} xp{worn ? ` · ${worn}` : ''}</Text>
          </Text>
          <Text color={ORANGE} wrap="truncate-end">{bar(p.xp - from, to - from, fullW)}</Text>
          <Text> </Text>
          {group('Daily', p.quests.items)}
          {sweepClaimable(p, now) && (
            <Box flexDirection="row">
              <Button key="claim-sweep" label={`Claim +${XP.sweep} xp`} hotkey="c" variant="primary" onPress={() => claimSweep($)} />
            </Box>
          )}
          {projectBoard && group(`Project: ${projectBoard.campaign}`, projectBoard.items)}
          <Text> </Text>
          <Text dimColor wrap="truncate-end">Trophies {unlockedCount}/{ACHIEVEMENTS.length} · {project || 'this project'}</Text>
          <Text dimColor wrap="truncate-end">
            <Text color={ORANGE}>/quests</Text>
            {' project quests · '}
            <Text color={ORANGE}>/pet</Text>
            {' hide'}
          </Text>
        </Box>
      )
    }

    if (e.surface !== 'desktop' && e.surface !== 'vscode' && e.surface !== 'mobile') return next(e)
    const { Box, Text, Button, Svg } = $.ui.resolve(e)
    const hatNow: AnyHat = wornCustom ?? p.hat
    // Bars shrink with a narrow pane so the numbers after them stay in view.
    const barW = Math.max(8, Math.min(20, cols - 28))
    // A thin dim line between sections: it sits where a blank row would, so it adds no height.
    const rule = () => <Text dimColor wrap="truncate-end">{'─'.repeat(fullW)}</Text>
    // Stacks the parts that are there with a rule between each two, no other gap.
    const sections = (...parts: RenderChildren[]) => (
      <Box flexDirection="column">
        {parts.filter(part => part !== false && part !== null && part !== undefined).flatMap((part, i) => (i === 0 ? [part] : [rule(), part]))}
      </Box>
    )
    // Like sections, but the first part (the room, an intro line) stands free: a gap, no rule, under it.
    const led = (lead: RenderChildren, ...parts: RenderChildren[]) => (
      <Box flexDirection="column" gap={1}>
        {lead}
        {sections(...parts)}
      </Box>
    )
    // Today's Daily Sweep bonus, while it waits for its claim (it expires at midnight).
    const claim = sweepClaimable(p, now) && (
      <Box flexDirection="row" alignItems="center" gap={1}>
        <Button key="claim-sweep" label={`Claim +${XP.sweep} xp`} variant="primary" onPress={() => claimSweep($)} />
        <Text dimColor wrap="truncate-end">Daily Sweep: every daily quest done</Text>
      </Box>
    )

    const QuestRow = (q: Quest, why?: string) => (
      <Box flexDirection="column">
        <Text wrap="truncate-end">
          <Text color={q.done ? GREEN : ORANGE}>{q.done ? '[x] ' : '[ ] '}</Text>
          <Text bold={!q.done} dimColor={q.done}>{q.title}</Text>
          <Text dimColor>   +{q.xp} xp</Text>
        </Text>
        {why !== undefined && why !== '' && <Text dimColor wrap="truncate-end">    {why}</Text>}
        <Text wrap="truncate-end">
          <Text color={q.done ? GREEN : ORANGE}>    {bar(Math.min(q.progress, q.goal), q.goal, barW)}</Text>
          <Text dimColor>  {amount(q)}</Text>
        </Text>
      </Box>
    )

    const tabBar = (
      <Box flexDirection="row" gap={1} flexWrap="wrap">
        {TABS.map(item => (
          <Button key={`tab-${item.id}`} label={item.label} variant={item.id === current ? 'primary' : 'secondary'} onPress={() => update($, tab, () => item.id)} />
        ))}
      </Box>
    )

    // The level and its xp count on one line, the bar across the whole pane below.
    const header = (
      <Box flexDirection="column">
        <Text wrap="truncate-end">
          <Text bold color={ORANGE}>Lv {level}</Text>
          <Text dimColor>  {xpText} xp</Text>
        </Text>
        <Text color={ORANGE} wrap="truncate-end">{bar(p.xp - from, to - from, fullW)}</Text>
      </Box>
    )

    // An empty project section points at the Quests tab, where the button lives.
    const gotoQuests = (key: string) => (
      <Box flexDirection="row">
        <Button key={key} label="Get project quests" variant="secondary" onPress={() => update($, tab, () => 'quests')} />
      </Box>
    )

    let body
    if (current === 'quests') {
      const gen = await read($, questGen)
      const isWorking = gen.status === 'working'
      const gate = projectBoard ? canRegenerate(projectBoard, now) : { ok: true }
      const dailyDone = p.quests.items.filter(q => q.done).length
      const projectDone = projectBoard?.items.filter(q => q.done).length ?? 0
      body = sections(
        <Box flexDirection="column" gap={1}>
          <Text bold>Daily quests <Text dimColor>{dailyDone}/{p.quests.items.length} · resets at midnight</Text></Text>
          {p.quests.items.map(q => QuestRow(q))}
          {claim}
        </Box>,
        <Box flexDirection="column" gap={1}>
          <Text bold wrap="truncate-end">
            Project quests{projectBoard ? `: ${projectBoard.campaign}` : ''}
            {projectBoard && projectBoard.items.length > 0 && <Text dimColor> {projectDone}/{projectBoard.items.length}</Text>}
          </Text>
          {isWorking && <Text color={ORANGE}>{gen.message}</Text>}
          {gen.status === 'error' && <Text color={RED} wrap="wrap">{gen.message}</Text>}
          {!projectBoard && !isWorking && (
            <Text dimColor>No quests for {project || 'this project'} yet. Clawd can read the project and invent some.</Text>
          )}
          {projectBoard?.items.map(q => QuestRow(q, q.why))}
          {projectBoard?.isComplete && projectBoard.items.length > 0 && (
            <Text>
              <Text color={GOLD}>★ </Text>
              <Text bold>Campaign complete. Clawd is proud of you.</Text>
            </Text>
          )}
          {!gate.ok && !isWorking ? (
            <Text dimColor>New project quests unlock when this campaign is done, or tomorrow.</Text>
          ) : (
            <Box flexDirection="row" gap={1}>
              <Button
                key="gen-quests"
                label={isWorking ? 'Scouting…' : projectBoard ? 'New project quests' : 'Generate project quests'}
                variant={isWorking ? 'secondary' : 'primary'}
                onPress={isWorking ? () => undefined : () => generateQuests($, '')}
              />
            </Box>
          )}
        </Box>,
      )
    } else if (current === 'trophies') {
      const isExpanded = await read($, expandTrophies)
      const all = achievementProgress(p)
      const unlocked = all.filter(a => a.unlocked)
      const hiddenLeft = ACHIEVEMENTS.filter(a => a.hidden).length - unlocked.filter(a => a.def.hidden).length
      const locked = all.filter(a => !a.unlocked && !a.def.hidden).sort((a, b) => ratio(b.progress) - ratio(a.progress))
      const nextUp = locked.slice(0, 3)
      const moreLocked = locked.slice(3)
      const milestones = projectBoard?.milestones ?? []
      body = sections(
        <Box flexDirection="column" gap={1}>
          <Text bold>Trophies {unlocked.length}/{ACHIEVEMENTS.length}</Text>
          {nextUp.length > 0 && (
            <Box flexDirection="column">
              <Text bold>Next up</Text>
              {nextUp.map(a => (
                <Box flexDirection="column">
                  <Text wrap="truncate-end">
                    <Text dimColor>{'☆ '}</Text>
                    <Text>{a.def.name}</Text>
                    <Text dimColor>{' — '}{a.def.description}</Text>
                  </Text>
                  {a.progress && (
                    <Text wrap="truncate-end">
                      <Text color={ORANGE}>    {bar(a.progress.value, a.progress.goal, barW)}</Text>
                      <Text dimColor>  {Math.min(a.progress.value, a.progress.goal)}/{a.progress.goal}</Text>
                    </Text>
                  )}
                </Box>
              ))}
            </Box>
          )}
        </Box>,
          <Box flexDirection="column">
            <Text bold wrap="truncate-end">Project trophies{project ? `: ${project}` : ''}</Text>
            {!projectBoard && <Text dimColor>No project trophies yet.</Text>}
            {!projectBoard && gotoQuests('goto-quests-trophies')}
            {projectBoard && milestones.length === 0 && <Text dimColor>Run /quests and Clawd sets milestones for this project.</Text>}
            {milestones.map(m => (
              <Box flexDirection="column">
                <Text wrap="truncate-end">
                  <Text color={m.done ? GOLD : undefined} dimColor={!m.done}>{m.done ? '★ ' : '☆ '}</Text>
                  <Text bold={m.done} dimColor={!m.done}>{m.name}</Text>
                  <Text dimColor>{' — '}{m.description}</Text>
                </Text>
                {!m.done && (
                  <Text wrap="truncate-end">
                    <Text color={ORANGE}>    {bar(m.progress, m.goal, barW)}</Text>
                    <Text dimColor>  {m.progress}/{m.goal} · +{m.xp} xp</Text>
                  </Text>
                )}
              </Box>
            ))}
          </Box>,
          <Box flexDirection="column">
            <Text bold>Unlocked</Text>
            {unlocked.length === 0 && <Text dimColor>None yet. Keep going.</Text>}
            {unlocked.map(a => (
              <Text wrap="truncate-end">
                <Text color={GOLD}>★ </Text>
                <Text bold>{a.def.name}</Text>
                <Text dimColor>{' — '}{a.def.description}</Text>
              </Text>
            ))}
          </Box>,
          (moreLocked.length > 0 || hiddenLeft > 0) && (
            <Box flexDirection="column">
              <Box flexDirection="row">
                <Button key="toggle-locked" label={isExpanded ? 'Hide locked' : `Show all locked (${moreLocked.length + hiddenLeft})`} variant="secondary" onPress={() => update($, expandTrophies, v => !v)} />
              </Box>
              {isExpanded && moreLocked.map(a => (
                <Text wrap="truncate-end" dimColor>
                  {'☆ '}{a.def.name}{' — '}{a.def.description}{a.progress ? `  ${Math.min(a.progress.value, a.progress.goal)}/${a.progress.goal}` : ''}
                </Text>
              ))}
              {isExpanded && hiddenLeft > 0 && (
                <Text dimColor wrap="truncate-end">{'☆ '}???{' — '}{`${hiddenLeft} hidden ${hiddenLeft === 1 ? 'trophy' : 'trophies'} left to find`}</Text>
              )}
            </Box>
          ),
      )
    } else if (current === 'decor') {
      const roomDecor = resolveDecor(await read($, decor), p)
      // A small look at each slot as the room shows it now (empty room, cropped to the piece).
      const d = new Date(now)
      const previewBase: SceneInput = {
        mood: 'idle', activity: 'none', hat: null, hour: d.getHours(), minute: d.getMinutes(), month: d.getMonth() + 1, day: d.getDate(),
        helpers: 0, combo: 0, trophies: 0, plantStage: plantStage(p.totals.turns), level, coffee: await read($, coffee), decor: roomDecor,
      }
      const preview = (slot: DecorSlot) => {
        const crop = decorPreview(previewBase, slot, 1)
        const m = /viewBox="[\d.-]+ [\d.-]+ ([\d.]+) ([\d.]+)"/.exec(crop)
        if (!m) return null
        const scale = Math.min(72 / Number(m[1]), 44 / Number(m[2]), 3)
        return <Svg key={`decor-preview-${slot}-${roomDecor[slot]}`} source={crop} alt={`${slot} preview`} width={Math.round(Number(m[1]) * scale)} height={Math.round(Number(m[2]) * scale)} />
      }
      // What a locked piece takes, short: "Lv 4" or the trophy's name.
      const takes = (requirement: string) => requirement.replace(/^Level /, 'Lv ').replace(/^Trophy: /, '')
      // One compact row per slot: the preview beside its name and choices, the locked ones on one dim line.
      body = led(
        <Text dimColor>Rearrange Clawd's room. New pieces unlock with levels and trophies.</Text>,
        ...SLOTS.map(({ slot, label }) => {
          const items = DECOR.filter(d => d.slot === slot)
          const open = items.filter(d => isUnlocked(d, p))
          const locked = items.filter(d => !isUnlocked(d, p))
          return (
            <Box flexDirection="row" alignItems="center" gap={2}>
              {preview(slot)}
              <Box flexDirection="column" flexGrow={1} flexShrink={1}>
                <Text bold>{label}</Text>
                <Box flexDirection="row" gap={1} flexWrap="wrap">
                  {open.map(d => (
                    <Button key={`decor-${slot}-${d.id}`} label={d.name} variant={roomDecor[slot] === d.id ? 'primary' : 'secondary'} onPress={() => setDecor($, slot, d.id)} />
                  ))}
                </Box>
                {locked.length > 0 && (
                  <Text dimColor wrap="wrap">Locked: {locked.map(d => `${d.name} (${takes(d.requirement)})`).join(', ')}</Text>
                )}
              </Box>
            </Box>
          )
        }),
      )
    } else if (current === 'wardrobe') {
      const available = new Set(availableHats(p, now))
      const projectHats = unlockedProjectHats(projectBoard)
      const lockedHats = HATS.filter(item => !available.has(item.id))
      const lockedProjectHats = (projectBoard?.hats ?? []).filter(hat => !projectHats.some(u => u.id === hat.id))
      const mirrorW = Math.max(160, Math.min(cols * 8 - 16, 360))
      body = sections(
        <Box flexDirection="column" gap={1}>
          <Box flexDirection="row" justifyContent="center">
            <Svg key={`mirror-${wornCustom?.id ?? p.hat ?? 'none'}`} source={mini('happy', 'none', hatNow)} alt={`Clawd in the mirror${hatNow ? `, wearing the ${hatName(p.hat, wornCustom)}` : ''}`} width={mirrorW} height={Math.round(mirrorW * 76 / 160)} isInteractive />
          </Box>
          <Box flexDirection="row" gap={1} flexWrap="wrap">
            <Button key="hat-none" label="No hat" variant={hatNow === null ? 'primary' : 'secondary'} onPress={() => wear($, null)} />
            {HATS.filter(item => available.has(item.id)).map(hat => (
              <Button key={`hat-${hat.id}`} label={hat.name} variant={!wornCustom && p.hat === hat.id ? 'primary' : 'secondary'} onPress={() => wear($, hat.id)} />
            ))}
          </Box>
          {lockedHats.length > 0 && (
            <Box flexDirection="column">
              <Text dimColor>Locked</Text>
              {lockedHats.map(hat => (
                <Text dimColor wrap="truncate-end">{'· '}{hat.name}{' — '}{hat.requirement}</Text>
              ))}
            </Box>
          )}
        </Box>,
        <Box flexDirection="column" gap={1}>
          <Box flexDirection="column">
            <Text bold wrap="truncate-end">Project hats{project ? `: ${project}` : ''}</Text>
            {!projectBoard && <Text dimColor>No project hats yet.</Text>}
            {!projectBoard && gotoQuests('goto-quests-wardrobe')}
            {projectBoard && projectBoard.hats.length === 0 && <Text dimColor>Run /quests and Clawd designs hats for this project.</Text>}
          </Box>
          {projectHats.length > 0 && (
            <Box flexDirection="row" gap={1} flexWrap="wrap">
              {projectHats.map(hat => (
                <Button key={`phat-${hat.id}`} label={hat.name} variant={wornCustom?.id === hat.id ? 'primary' : 'secondary'} onPress={() => wearCustom($, hat)} />
              ))}
            </Box>
          )}
          {lockedProjectHats.length > 0 && (
            <Box flexDirection="column">
              <Text dimColor>Locked</Text>
              {lockedProjectHats.map(hat => {
                const milestone = projectBoard?.milestones.find(m => m.id === hat.milestoneId)
                return <Text dimColor wrap="truncate-end">{'· '}{hat.name}{' — '}{`Earn “${milestone?.name ?? 'a project trophy'}”`}</Text>
              })}
            </Box>
          )}
        </Box>,
      )
    } else {
      const d = new Date(now)
      const width = Math.max(180, Math.min(cols * 8 - 8, 1100))
      const shownScene = await read($, sceneAtom)
      const u = await read($, usageAtom)
      const scene: SceneInput = {
        mood: shownScene.mood, activity: shownScene.activity, hat: hatNow, hour: d.getHours(), minute: d.getMinutes(), month: d.getMonth() + 1, day: d.getDate(),
        // The walk and fades stay in the source for the whole scene; phaseSvg below makes a later
        // redraw resume them where they are (finished, usually) rather than replay them.
        fromX: shownScene.fromX ?? undefined,
        fromY: shownScene.fromY ?? undefined,
        fromMood: shownScene.fromMood ?? undefined,
        fromActivity: shownScene.fromActivity ?? undefined,
        helpers: await read($, helpers),
        combo: comboTier(comboCount),
        trophies: Object.keys(p.achievements).length + (projectBoard?.milestones.filter(m => m.done).length ?? 0),
        plantStage: plantStage(p.totals.turns),
        level,
        coffee: await read($, coffee),
        decor: resolveDecor(await read($, decor), p),
        usage: sceneUsage(u, now),
      }
      // The one quest to work on next (project quests first).
      const open: Quest[] = [...(projectBoard?.items ?? []), ...p.quests.items].filter(q => !q.done).slice(0, 1)
      // The next trophy, told by what it takes: open project milestones first, then the achievement closest to done.
      const nextTrophies: Array<{ name: string; value: number; goal: number }> = [
        ...(projectBoard?.milestones ?? []).filter(m => !m.done).map(m => ({ name: m.description, value: Math.min(m.progress, m.goal), goal: m.goal })),
        ...achievementProgress(p)
          .filter(a => !a.unlocked && a.progress && a.progress.goal > 0)
          .map(a => ({ name: a.def.description, value: Math.min(a.progress!.value, a.progress!.goal), goal: a.progress!.goal }))
          .sort((x, y) => y.value / y.goal - x.value / x.goal),
      ].slice(0, 1)
      // A brand-new room keeps to the intro: no empty trophy line, no empty log.
      const isNew = p.totals.tools === 0
      // What this project earned lately, newest first.
      const recent = [...(p.recent ?? [])].reverse()
      body = led(
          <Box flexDirection="column" alignItems="center">
            <Svg key="scene" source={phasedScene(sceneSvg(scene), shownScene.at, now, u.at)} alt={`Clawd's room, ${shownScene.mood}.${usageAlt(u, now)}`} width={width} height={Math.round(width * SCENE_RATIO)} isInteractive />
            <Text bold color={color}>{quip}</Text>
            {detail !== '' ? <Text dimColor wrap="truncate-end">{detail}</Text> : <Text> </Text>}
          </Box>,
          isNew && (
            <Box flexDirection="column">
              <Text dimColor>Clawd reacts to what Claude does. Every tool call earns xp.</Text>
              <Text dimColor>Daily quests reset at midnight; trophies unlock hats and decor.</Text>
              <Text dimColor>Try /quests for project-specific quests.</Text>
            </Box>
          ),
          <Box flexDirection="column">
            <Text bold>Next quest</Text>
            {open.length === 0 && claim}
            {open.length === 0 && !claim && <Text dimColor>All done for now. Try /quests for project quests.</Text>}
            {open.map(q => (
              <Text wrap="truncate-end">
                <Text color={ORANGE}>{bar(Math.min(q.progress, q.goal), q.goal, 8)}</Text>
                <Text dimColor>  {amount(q)}  </Text>
                <Text>{q.title}</Text>
                <Text dimColor>  +{q.xp} xp</Text>
              </Text>
            ))}
          </Box>,
          <Box flexDirection="column">
            <Text bold>Next trophy</Text>
            {!isNew && nextTrophies.length === 0 && Object.keys(p.achievements).length > 0 && (
              <Text dimColor>Every trophy in reach is yours. Try /quests for project trophies.</Text>
            )}
            {nextTrophies.map(t => (
              <Text wrap="truncate-end">
                <Text color={GOLD}>{bar(t.value, t.goal, 8)}</Text>
                <Text dimColor>  {t.value}/{t.goal}  </Text>
                <Text>{t.name}</Text>
              </Text>
            ))}
          </Box>,
          !isNew && (
            <Box flexDirection="column">
              <Text bold>Recent</Text>
              {recent.length === 0 && <Text dimColor>Nothing yet. Finished quests, trophies and level-ups show up here.</Text>}
              {recent.map(entry => (
                <Text wrap="truncate-end">
                  <Text color={GOLD}>{entry.verb}</Text>
                  <Text>{' · '}{entry.what}</Text>
                  <Text dimColor>{'  '}{ago(now - entry.at)}</Text>
                </Text>
              ))}
            </Box>
          ),
      )
    }

    // No rules around the xp header: plain gaps keep it airy without boxing it in.
    return (
      <Box flexDirection="column" gap={1}>
        {tabBar}
        {header}
        {body}
      </Box>
    )
  })

  on('ui.close', async ($, e, next) => {
    if (e.id === PANE && e.origin.kind === 'person') await update($, isHidden, () => true)
    return next(e)
  })
}

files.hooks/game.ts:
// Gamification engine for Clawd: xp, levels, streaks, daily quests, achievements and hats.
// Pure and deterministic: no Math.random, no Date.now, time arrives on every event as `now`.
import type { AchievementDef, Activity, GameEvent, GameResult, HatId, Profile, Quest } from '../types'

// ---------- tuning ----------

// The level curve is fixed (level = floor(sqrt(xp / 40)) + 1), so xp per action stays small:
// a solid first day (~150 tool calls, ~20 turns) lands around level 4, level 10 takes ~2-3 weeks.
export const XP = {
  light: 1,            // read / search / web / shell / git / skill: pays on every 2nd tool call overall (0.5 on average)
  craft: 1,            // successful edit / write / test / terraform: always pays
  agent: 2,            // successful subagent delegation
  error: 1,            // you learn from mistakes: pays on the 1st, 4th, 7th ... error (1/3 on average)
  comboEvery: 10,      // every 10th call of a combo pays a bonus ...
  comboMaxBonus: 3,    // ... of combo/10, capped at 3
  turn: 2,             // finished turn
  cleanTurn: 1,        // extra when the turn used tools and had no errors
  dailyBase: 10,       // first activity of a day
  dailyPerStreakDay: 2, // + 2 per streak day beyond the first ...
  dailyStreakCap: 10,  // ... counting at most 10 extra days (max 30)
  questScale: 0.6,     // quest rewards come out at roughly 10-25 xp
  sweep: 15,           // Daily Sweep: all 3 daily quests done, paid when claimed the same day
  achievement: { easy: 5, medium: 20, hard: 50, secret: 15 } as const,
} as const

// ---------- internal extension of the stored profile ----------
// Per-day counters that the shared Profile type has no room for. Kept as an optional extra
// JSON field so the stored object stays a valid Profile for everyone else.
type Daily = { day: string; exts: string[] }
type Stored = Profile & { daily?: Daily; sweeps?: number }

export const RECENT_SIZE = 5

// ---------- time helpers ----------

const pad = (n: number) => String(n).padStart(2, '0')

export function dayOf(now: number): string {
  const d = new Date(now)
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`
}

function parseDay(day: string): Date | null {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(day)
  if (!m) return null
  return new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]), 12)
}

function daysBetween(from: string, to: string): number {
  const a = parseDay(from), b = parseDay(to)
  if (!a || !b) return Infinity
  return Math.round((b.getTime() - a.getTime()) / 86_400_000)
}

const isWeekend = (d: Date) => d.getDay() === 0 || d.getDay() === 6

// A streak continues from `last` to `today` when they are consecutive days, or when every day
// strictly between them is a Saturday or Sunday (Friday -> Monday keeps the streak).
export function continues(last: string, today: string): boolean {
  const n = daysBetween(last, today)
  if (n === 1) return true
  if (!Number.isFinite(n) || n < 2 || n > 3) return false
  const d = parseDay(last)!
  for (let i = 1; i < n; i++) {
    d.setDate(d.getDate() + 1)
    if (!isWeekend(d)) return false
  }
  return true
}

// ---------- level ----------

export function levelOf(xp: number): { level: number; from: number; to: number } {
  const level = Math.floor(Math.sqrt(Math.max(0, xp) / 40)) + 1
  return { level, from: 40 * (level - 1) ** 2, to: 40 * level ** 2 }
}

// ---------- seeded PRNG ----------

function hashString(s: string): number {
  let h = 0x811c9dc5
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i)
    h = Math.imul(h, 0x01000193)
  }
  return h >>> 0
}

function mulberry32(seed: number): () => number {
  let a = seed >>> 0
  return () => {
    a = (a + 0x6d2b79f5) >>> 0
    let t = a
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

// ---------- activity helpers ----------

const EDITS: ReadonlySet<Activity> = new Set(['edit', 'write'])
const RUNS: ReadonlySet<Activity> = new Set(['shell', 'git', 'terraform', 'test'])

function normExt(ext: string | null): string | null {
  if (!ext) return null
  const e = ext.trim().replace(/^\.+/, '').toLowerCase()
  return /^[a-z0-9_+-]{1,12}$/.test(e) ? e : null
}

const isTf = (activity: Activity, ext: string | null) =>
  activity === 'terraform' || (EDITS.has(activity) && (ext === 'tf' || ext === 'tfvars'))

// ---------- quests ----------

type QuestCtx = { event: GameEvent; daily: Daily }
type QuestTemplate = {
  id: string
  weight: number
  goal: [number, number]
  title: (goal: number, param: number) => string
  xp: (goal: number) => number
  param?: [number, number] // optional second parameter (e.g. seconds); goal is then usually 1
  // progress: return { add } to increment, { set } to raise progress to a value, or null
  track: (ctx: QuestCtx, quest: Quest, param: number) => { add?: number; set?: number } | null
}

const okTool = (e: GameEvent, pred: (a: Activity) => boolean) =>
  e.type === 'tool' && !e.isError && pred(e.activity)

const QUEST_TEMPLATES: QuestTemplate[] = [
  { id: 'edit', weight: 3, goal: [5, 12], title: g => `Edit ${g} files`, xp: g => 15 + g * 2,
    track: ({ event }) => okTool(event, a => EDITS.has(a)) ? { add: 1 } : null },
  { id: 'clean', weight: 3, goal: [3, 5], title: g => `Finish ${g} turns without errors`, xp: g => 15 + g * 5,
    track: ({ event }) => event.type === 'turn' && event.toolCount > 0 && event.errorCount === 0 ? { add: 1 } : null },
  { id: 'read', weight: 2, goal: [10, 20], title: g => `Read ${g} files`, xp: g => 15 + g,
    track: ({ event }) => okTool(event, a => a === 'read') ? { add: 1 } : null },
  { id: 'combo', weight: 2, goal: [8, 15], title: g => `Reach a ${g}-combo`, xp: g => 10 + g * 2,
    track: ({ event }) => event.type === 'tool' && !event.isError ? { set: event.combo } : null },
  { id: 'fast', weight: 2, goal: [1, 1], param: [3, 6], title: (_g, p) => `Finish a turn in under ${p * 10} seconds`, xp: () => 25,
    track: ({ event }, _q, p) => event.type === 'turn' && event.toolCount > 0 && event.durationMs < p * 10_000 ? { add: 1 } : null },
  { id: 'turns', weight: 2, goal: [5, 10], title: g => `Finish ${g} turns`, xp: g => 15 + g * 2,
    track: ({ event }) => event.type === 'turn' ? { add: 1 } : null },
  { id: 'prompts', weight: 2, goal: [5, 10], title: g => `Send ${g} prompts`, xp: g => 10 + g * 2,
    track: ({ event }) => event.type === 'prompt' ? { add: 1 } : null },
  { id: 'tools', weight: 2, goal: [40, 80], title: g => `Make ${g} tool calls`, xp: g => 15 + Math.round(g / 4),
    track: ({ event }) => event.type === 'tool' ? { add: 1 } : null },
]

const TEMPLATE_BY_ID = new Map(QUEST_TEMPLATES.map(t => [t.id, t]))

// Three quests for a day, deterministic per day. Every quest fits any project (no tests, git or
// codebase searches), so a docs or notes folder gets quests it can finish too.
export function questsForDay(day: string): Quest[] {
  const rnd = mulberry32(hashString(`clawd-quests:${day}`))
  const range = ([lo, hi]: [number, number]) => lo + Math.floor(rnd() * (hi - lo + 1))
  const pool = [...QUEST_TEMPLATES]
  const out: Quest[] = []
  while (out.length < 3 && pool.length > 0) {
    const total = pool.reduce((s, t) => s + t.weight, 0)
    let r = rnd() * total
    let idx = 0
    for (; idx < pool.length - 1; idx++) {
      r -= pool[idx]!.weight
      if (r < 0) break
    }
    const t = pool.splice(idx, 1)[0]!
    const goal = range(t.goal)
    const param = t.param ? range(t.param) : 0
    out.push({
      id: t.param ? `${t.id}:${param}` : t.id,
      title: t.title(goal, param),
      goal,
      progress: 0,
      xp: Math.max(5, Math.round(t.xp(goal) * XP.questScale)),
      done: false,
    })
  }
  return out
}

// ---------- achievements ----------

type Tier = 'easy' | 'medium' | 'hard' | 'secret'
type TimeInfo = { hour: number; weekday: number; month: number; date: number }
type CheckCtx = { event: GameEvent; time: TimeInfo; level: number; gapDays: number | null }
type Achievement = AchievementDef & {
  tier: Tier
  check: (p: Profile, c: CheckCtx) => boolean
  goal?: (p: Profile) => { value: number; goal: number }
}

const count = (id: string, name: string, description: string, tier: Tier, goal: number,
  value: (p: Profile) => number): Achievement => ({
  id, name, description, tier,
  check: p => value(p) >= goal,
  goal: p => ({ value: Math.min(value(p), goal), goal }),
})

const promptMatch = (e: GameEvent, f: (text: string) => boolean) => e.type === 'prompt' && f(e.text)
const working = (e: GameEvent) => e.type === 'tool' || e.type === 'prompt' || e.type === 'turn' || e.type === 'session'

function isShouting(text: string): boolean {
  if ((text.match(/!/g)?.length ?? 0) >= 3) return true
  const letters = text.replace(/[^A-Za-z]/g, '')
  return letters.length >= 12 && letters === letters.toUpperCase()
}

const LIST: Achievement[] = [
  // getting started
  count('first-steps', 'First Steps', 'Make your first tool call', 'easy', 1, p => p.totals.tools),
  count('hello-world', 'Hello World', 'Edit your first file', 'easy', 1, p => p.totals.edits),
  // volume
  count('hundred-club', 'Hundred Club', 'Make 100 tool calls', 'easy', 100, p => p.totals.tools),
  count('thousand-hands', 'Thousand Hands', 'Make 1,000 tool calls', 'medium', 1000, p => p.totals.tools),
  count('legion', 'Legion', 'Make 10,000 tool calls', 'hard', 10000, p => p.totals.tools),
  count('bookworm', 'Bookworm', 'Read 100 files', 'medium', 100, p => p.totals.reads),
  count('sherlock', 'Sherlock', 'Search the codebase 100 times', 'medium', 100, p => p.totals.searches),
  count('wordsmith', 'Wordsmith', 'Edit 500 files', 'hard', 500, p => p.totals.edits),
  count('surfer', 'Web Surfer', 'Look things up on the web 25 times', 'medium', 25, p => p.totals.web),
  count('chatterbox', 'Chatterbox', 'Finish 100 turns', 'medium', 100, p => p.totals.turns),
  count('fail-forward', 'Fail Forward', 'Hit 100 errors and keep going', 'medium', 100, p => p.totals.errors),
  // specialties
  count('polyglot', 'Polyglot', 'Edit 5 different file types', 'medium', 5, p => p.fileTypes.length),
  count('terraformer', 'Terraformer', 'Make 25 Terraform changes', 'medium', 25, p => p.totals.tfEdits),
  count('git-gud', 'Git Gud', 'Run 50 git commands', 'medium', 50, p => p.totals.gitCommands),
  count('test-pilot', 'Test Pilot', 'Run the tests 25 times', 'medium', 25, p => p.totals.tests),
  count('manager', 'Manager Material', 'Delegate to subagents 10 times', 'medium', 10, p => p.totals.agents),
  count('explorer', 'Explorer', 'Work in this project on 5 different days', 'medium', 5, p => p.totals.days),
  // flow
  count('combo-10', 'On a Roll', 'Reach a 10-combo', 'easy', 10, p => p.bestCombo),
  count('combo-25', 'Unstoppable', 'Reach a 25-combo', 'medium', 25, p => p.bestCombo),
  count('combo-50', 'In the Zone', 'Reach a 50-combo', 'hard', 50, p => p.bestCombo),
  { id: 'clean-sweep', name: 'Clean Sweep', description: 'Finish a turn with 10+ tool calls and no errors', tier: 'medium',
    check: (_p, { event: e }) => e.type === 'turn' && e.toolCount >= 10 && e.errorCount === 0 },
  { id: 'speedrun', name: 'Speedrun', description: 'Finish a turn with 3+ tool calls in under 15 seconds', tier: 'easy',
    check: (_p, { event: e }) => e.type === 'turn' && e.toolCount >= 3 && e.durationMs < 15_000 },
  { id: 'marathon', name: 'Marathon', description: 'Finish a turn that ran longer than 20 minutes', tier: 'medium',
    check: (_p, { event: e }) => e.type === 'turn' && e.durationMs > 20 * 60_000 },
  { id: 'persistence', name: 'Persistence', description: 'Finish a turn despite 5+ errors', tier: 'easy',
    check: (_p, { event: e }) => e.type === 'turn' && e.errorCount >= 5 },
  // time of day
  { id: 'night-owl', name: 'Night Owl', description: 'Work between midnight and 5 am', tier: 'easy',
    check: (_p, { event, time }) => working(event) && time.hour < 5 },
  { id: 'early-bird', name: 'Early Bird', description: 'Work between 5 and 7 am', tier: 'easy',
    check: (_p, { event, time }) => working(event) && time.hour >= 5 && time.hour < 7 },
  { id: 'weekend', name: 'Weekend Warrior', description: 'Work on a Saturday or Sunday', tier: 'easy',
    check: (_p, { event, time }) => working(event) && (time.weekday === 0 || time.weekday === 6) },
  // streaks
  count('streak-3', 'Habit Forming', 'Keep a 3-day streak', 'easy', 3, p => p.streak.count),
  count('streak-7', 'Seven Days Strong', 'Keep a 7-day streak', 'medium', 7, p => p.streak.count),
  count('streak-30', 'Unbreakable', 'Keep a 30-day streak', 'hard', 30, p => p.streak.count),
  // Clawd
  // prompts
  { id: 'polite', name: 'Polite', description: 'Say please or thank you to Claude', tier: 'easy',
    check: (_p, { event }) => promptMatch(event, t => /\b(please|pls|thanks|thank you|thx|cheers)\b/i.test(t)) },
  { id: 'rubber-duck', name: 'Rubber Duck', description: 'Ask Claude a why question', tier: 'easy',
    check: (_p, { event }) => promptMatch(event, t => /\bwhy\b/i.test(t) && t.trim().endsWith('?')) },
  // levels
  { id: 'level-5', name: 'Apprentice', description: 'Reach level 5', tier: 'easy', check: (_p, c) => c.level >= 5,
    goal: p => ({ value: Math.min(levelOf(p.xp).level, 5), goal: 5 }) },
  { id: 'level-10', name: 'Journeyman', description: 'Reach level 10', tier: 'medium', check: (_p, c) => c.level >= 10,
    goal: p => ({ value: Math.min(levelOf(p.xp).level, 10), goal: 10 }) },
  { id: 'level-25', name: 'Grandmaster', description: 'Reach level 25', tier: 'hard', check: (_p, c) => c.level >= 25,
    goal: p => ({ value: Math.min(levelOf(p.xp).level, 25), goal: 25 }) },
  // hidden
  { id: 'my-machine', name: 'It Works on My Machine', description: 'Blame the environment', tier: 'secret', hidden: true,
    check: (_p, { event }) => promptMatch(event, t => /works on my machine/i.test(t)) },
  { id: 'ship-it', name: 'Ship It', description: 'Approve with confidence', tier: 'secret', hidden: true,
    check: (_p, { event }) => promptMatch(event, t => /\bship it\b|\blgtm\b/i.test(t)) },
  { id: 'rage-quit', name: 'Rage Quit Averted', description: 'Shout at Claude and stay anyway', tier: 'secret', hidden: true,
    check: (_p, { event }) => promptMatch(event, isShouting) },
  { id: 'teapot', name: '418', description: 'I am a teapot', tier: 'secret', hidden: true,
    check: (_p, { event }) => promptMatch(event, t => /teapot/i.test(t)) },
  { id: 'welcome-back', name: 'Welcome Back', description: 'Return after two weeks away', tier: 'secret', hidden: true,
    check: (_p, c) => c.gapDays !== null && c.gapDays >= 14 },
  { id: 'trick-or-commit', name: 'Trick or Commit', description: 'Work on Halloween', tier: 'secret', hidden: true,
    check: (_p, { event, time }) => working(event) && time.month === 10 && time.date === 31 },
  { id: 'holiday-coder', name: 'Holiday Coder', description: 'Work between December 24 and 26', tier: 'secret', hidden: true,
    check: (_p, { event, time }) => working(event) && time.month === 12 && time.date >= 24 && time.date <= 26 },
]

const BY_ID = new Map(LIST.map(a => [a.id, a]))
const defOf = (a: Achievement): AchievementDef =>
  a.hidden ? { id: a.id, name: a.name, description: a.description, hidden: true } : { id: a.id, name: a.name, description: a.description }

export const ACHIEVEMENTS: AchievementDef[] = LIST.map(defOf)

export function achievementProgress(profile: Profile): Array<{ def: AchievementDef; unlocked: boolean; progress?: { value: number; goal: number } }> {
  const out: Array<{ def: AchievementDef; unlocked: boolean; progress?: { value: number; goal: number } }> = []
  for (const a of LIST) {
    const unlocked = profile.achievements[a.id] !== undefined
    if (a.hidden && !unlocked) continue
    const entry: { def: AchievementDef; unlocked: boolean; progress?: { value: number; goal: number } } = { def: defOf(a), unlocked }
    if (a.goal) entry.progress = unlocked ? { value: a.goal(profile).goal, goal: a.goal(profile).goal } : a.goal(profile)
    out.push(entry)
  }
  return out
}

// ---------- hats ----------

export const HATS: Array<{ id: HatId; name: string; requirement: string }> = [
  { id: 'party', name: 'Party Hat', requirement: 'Level 2' },
  { id: 'beanie', name: 'Beanie', requirement: 'Keep a 3-day streak' },
  { id: 'headphones', name: 'Headphones', requirement: 'Make 100 tool calls' },
  { id: 'sunglasses', name: 'Sunglasses', requirement: 'Unlock Speedrun' },
  { id: 'tophat', name: 'Top Hat', requirement: 'Be polite to Claude' },
  { id: 'hardhat', name: 'Hard Hat', requirement: 'Unlock Terraformer or Test Pilot' },
  { id: 'propeller', name: 'Propeller Cap', requirement: 'Unlock Unstoppable (25-combo)' },
  { id: 'wizard', name: 'Wizard Hat', requirement: 'Unlock Polyglot or reach Level 10' },
  { id: 'halo', name: 'Halo', requirement: 'Unlock both Clean Sweep and Seven Days Strong' },
  { id: 'crown', name: 'Crown', requirement: 'Level 25 or a 30-day streak' },
  { id: 'pumpkin', name: 'Pumpkin', requirement: 'Any day in October; Halloween keeps it' },
  { id: 'santa', name: 'Santa Hat', requirement: 'Any day in December; Dec 24-26 keeps it' },
]

export function availableHats(profile: Profile, now: number): HatId[] {
  const has = (id: string) => profile.achievements[id] !== undefined
  const level = levelOf(profile.xp).level
  const month = new Date(now).getMonth() + 1
  const ok: Record<HatId, boolean> = {
    party: level >= 2,
    beanie: has('streak-3'),
    headphones: has('hundred-club'),
    sunglasses: has('speedrun'),
    tophat: has('polite'),
    hardhat: has('terraformer') || has('test-pilot'),
    propeller: has('combo-25'),
    wizard: has('polyglot') || level >= 10,
    halo: has('clean-sweep') && has('streak-7'),
    crown: level >= 25 || has('streak-30'),
    pumpkin: month === 10 || has('trick-or-commit'),
    santa: month === 12 || has('holiday-coder'),
  }
  return HATS.map(h => h.id).filter(id => ok[id])
}

// ---------- profile creation / migration ----------

const TOTAL_KEYS = ['tools', 'edits', 'reads', 'runs', 'searches', 'web', 'errors', 'turns',
  'gitCommands', 'tfEdits', 'tests', 'agents', 'days'] as const
const HAT_IDS: ReadonlySet<string> = new Set(HATS.map(h => h.id))

export const PROFILE_VERSION = 1

// A save written by a newer clawd-quest: shown as far as we understand it, never overwritten.
export function isNewerProfile(raw: unknown): boolean {
  return isObj(raw) && typeof raw.version === 'number' && raw.version > PROFILE_VERSION
}

export function newProfile(): Profile {
  return {
    version: PROFILE_VERSION,
    xp: 0,
    totals: { tools: 0, edits: 0, reads: 0, runs: 0, searches: 0, web: 0, errors: 0, turns: 0, gitCommands: 0, tfEdits: 0, tests: 0, agents: 0, days: 0 },
    fileTypes: [],
    projects: [],
    achievements: {},
    streak: { count: 0, lastDay: '' },
    quests: { day: '', items: [] },
    hat: null,
    bestCombo: 0,
    sweepClaimed: '',
  }
}

const isObj = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v)
const num = (v: unknown, fallback = 0) => (typeof v === 'number' && Number.isFinite(v) && v >= 0 ? Math.floor(v) : fallback)
const strList = (v: unknown, max = 200) =>
  Array.isArray(v) ? [...new Set(v.filter((x): x is string => typeof x === 'string' && x.length > 0 && x.length <= 120))].slice(0, max) : []
const dayStr = (v: unknown) => (typeof v === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(v) ? v : '')

function migrateQuest(v: unknown): Quest | null {
  if (!isObj(v) || typeof v.id !== 'string' || typeof v.title !== 'string') return null
  const goal = Math.max(1, num(v.goal, 1))
  const progress = Math.min(goal, num(v.progress))
  return { id: v.id, title: v.title, goal, progress, xp: num(v.xp), done: v.done === true }
}

export function migrateProfile(raw: unknown): Profile {
  let src: unknown = raw
  if (typeof src === 'string') {
    try { src = JSON.parse(src) } catch { src = null }
  }
  const p = newProfile() as Stored
  if (!isObj(src)) return p
  p.xp = num(src.xp)
  const totals = isObj(src.totals) ? src.totals : {}
  for (const k of TOTAL_KEYS) p.totals[k] = num(totals[k])
  p.fileTypes = [...new Set(strList(src.fileTypes).map(normExt).filter((s): s is string => s !== null))]
  p.projects = strList(src.projects)
  if (isObj(src.achievements)) {
    for (const [k, v] of Object.entries(src.achievements)) {
      if (typeof v === 'number' && Number.isFinite(v)) p.achievements[k] = v
      else if (v === true) p.achievements[k] = 0 // older shape: id -> true
    }
  } else if (Array.isArray(src.achievements)) {
    for (const k of src.achievements) if (typeof k === 'string') p.achievements[k] = 0 // older shape: id list
  }
  if (isObj(src.streak)) p.streak = { count: num(src.streak.count), lastDay: dayStr(src.streak.lastDay) }
  if (isObj(src.quests) && Array.isArray(src.quests.items)) {
    const day = dayStr(src.quests.day)
    // A stored quest whose kind is gone (petting, tests, git, ...) could never finish: today's draw fills its place.
    const known = (q: Quest | null): q is Quest => q !== null && TEMPLATE_BY_ID.has(q.id.split(':')[0] ?? '')
    const all = src.quests.items.map(migrateQuest).filter((q): q is Quest => q !== null)
    const items = all.filter(known)
    if (day && items.length < all.length) {
      for (const q of questsForDay(day)) if (items.length < 3 && !items.some(i => i.id === q.id)) items.push(q)
    }
    p.quests = day ? { day, items } : { day: '', items: [] }
  }
  p.hat = typeof src.hat === 'string' && HAT_IDS.has(src.hat) ? (src.hat as HatId) : null
  p.bestCombo = num(src.bestCombo)
  if (isObj(src.daily) && dayStr(src.daily.day)) {
    p.daily = { day: dayStr(src.daily.day), exts: strList(src.daily.exts, 50) }
  }
  p.sweeps = num(src.sweeps)
  // A save from before the claim button got its sweep paid on the spot: that day counts as claimed.
  p.sweepClaimed = typeof src.sweepClaimed === 'string' ? dayStr(src.sweepClaimed)
    : p.quests.day && p.quests.items.length >= 3 && p.quests.items.every(q => q.done) ? p.quests.day : ''
  if (Array.isArray(src.recent)) {
    p.recent = src.recent
      .filter((r): r is Record<string, unknown> => isObj(r) && typeof r.verb === 'string' && typeof r.what === 'string')
      .map(r => ({ verb: String(r.verb), what: String(r.what), at: num(r.at) }))
      .slice(-RECENT_SIZE)
  }
  return p
}

function clone(p: Profile): Stored {
  const s = p as Stored
  const out: Stored = {
    ...p,
    totals: { ...p.totals },
    fileTypes: [...p.fileTypes],
    projects: [...p.projects],
    achievements: { ...p.achievements },
    streak: { ...p.streak },
    quests: { day: p.quests.day, items: p.quests.items.map(q => ({ ...q })) },
  }
  if (s.daily) out.daily = { ...s.daily, exts: [...s.daily.exts] }
  if (p.recent) out.recent = p.recent.map(r => ({ ...r }))
  return out
}

// ---------- the core ----------

// `tools` and `errors` are the running totals after this call; they spread the half-point
// (light tools) and third-point (errors) rewards deterministically.
function toolXp(activity: Activity, isError: boolean, combo: number, tools: number, errors: number): number {
  if (isError) return errors % 3 === 1 ? XP.error : 0
  let xp = activity === 'agent' ? XP.agent
    : EDITS.has(activity) || activity === 'test' || activity === 'terraform' ? XP.craft
    : tools % 2 === 0 ? XP.light : 0
  if (combo > 0 && combo % XP.comboEvery === 0) xp += Math.min(combo / XP.comboEvery, XP.comboMaxBonus)
  return xp
}

function timeInfo(now: number): TimeInfo {
  const d = new Date(now)
  return { hour: d.getHours(), weekday: d.getDay(), month: d.getMonth() + 1, date: d.getDate() }
}

export function applyEvent(profile: Profile, event: GameEvent): GameResult {
  const before = profile
  const p = clone(profile)
  const now = Number.isFinite(event.now) ? event.now : 0
  const today = dayOf(now)
  let xp = 0
  let gapDays: number | null = null

  // day rollover: fresh quests and per-day counters
  const prevQuestDay = p.quests.day
  if (p.quests.day !== today) p.quests = { day: today, items: questsForDay(today) }
  if (!p.daily || p.daily.day !== today) p.daily = { day: today, exts: [] }
  const daily = p.daily

  // streak + daily bonus on the first real activity of a day (a prompt or a tool call;
  // opening a session, bonus xp and a claim do not count)
  const ev = event
  if ((ev.type === 'prompt' || ev.type === 'tool') && p.streak.lastDay !== today) {
    const last = p.streak.lastDay
    if (last) gapDays = daysBetween(last, today)
    p.streak = { count: last && continues(last, today) ? p.streak.count + 1 : 1, lastDay: today }
    p.totals.days++
    xp += XP.dailyBase + XP.dailyPerStreakDay * Math.min(p.streak.count - 1, XP.dailyStreakCap)
  }

  switch (ev.type) {
    case 'bonus':
      xp += Math.max(0, Math.floor(ev.xp) || 0)
      break
    case 'claim':
      // the Daily Sweep bonus, once, only on the day its quests were done (the rollover above expired it)
      if (sweepClaimable(p, now)) {
        xp += XP.sweep
        p.sweepClaimed = today
      }
      break
    case 'session': {
      const name = ev.project.trim().slice(0, 120)
      if (name && !p.projects.includes(name)) p.projects.push(name)
      break
    }
    case 'prompt':
      break
    case 'tool': {
      const t = p.totals
      const ext = normExt(ev.ext)
      t.tools++
      if (ev.isError) {
        t.errors++
      } else {
        const a = ev.activity
        if (EDITS.has(a)) {
          t.edits++
          if (ext) {
            if (!p.fileTypes.includes(ext)) p.fileTypes.push(ext)
            if (!daily.exts.includes(ext)) daily.exts.push(ext)
          }
        }
        if (a === 'read') t.reads++
        if (a === 'search') t.searches++
        if (a === 'web') t.web++
        if (RUNS.has(a)) t.runs++
        if (a === 'git') t.gitCommands++
        if (a === 'test') t.tests++
        if (a === 'agent') t.agents++
        if (isTf(a, ext)) t.tfEdits++
        p.bestCombo = Math.max(p.bestCombo, Math.max(0, Math.floor(ev.combo) || 0))
      }
      xp += toolXp(ev.activity, ev.isError, Math.max(0, Math.floor(ev.combo) || 0), t.tools, t.errors)
      break
    }
    case 'turn':
      p.totals.turns++
      xp += XP.turn
      if (ev.toolCount > 0 && ev.errorCount === 0) xp += XP.cleanTurn
      break
  }

  // quests
  const completedQuests: Quest[] = []
  for (const q of p.quests.items) {
    if (q.done || ev.type === 'bonus' || ev.type === 'claim') continue
    const [tid, param] = q.id.split(':')
    const tpl = TEMPLATE_BY_ID.get(tid ?? '')
    if (!tpl) continue
    const r = tpl.track({ event, daily }, q, Number(param) || 0)
    if (!r) continue
    const next = r.set !== undefined ? Math.max(q.progress, r.set) : q.progress + (r.add ?? 0)
    q.progress = Math.min(q.goal, next)
    if (q.progress >= q.goal) {
      q.done = true
      xp += q.xp
      completedQuests.push({ ...q })
    }
  }
  // Daily Sweep: the event that finishes the last daily quest counts the sweep (so a trophy built on it
  // never hangs on a click); its bonus waits for the claim button until midnight
  if (completedQuests.length > 0 && p.quests.items.length >= 3 && p.quests.items.every(q => q.done)) {
    p.sweeps = (p.sweeps ?? 0) + 1
  }

  // achievements (looped: bonus xp may unlock a level achievement)
  const time = timeInfo(now)
  const unlocked: AchievementDef[] = []
  p.xp = before.xp + xp
  for (let round = 0; round < 4; round++) {
    const ctx: CheckCtx = { event, time, level: levelOf(p.xp).level, gapDays }
    let found = false
    for (const a of LIST) {
      if (p.achievements[a.id] !== undefined) continue
      if (!a.check(p, ctx)) continue
      p.achievements[a.id] = now
      p.xp += XP.achievement[a.tier]
      xp += XP.achievement[a.tier]
      unlocked.push(defOf(a))
      found = true
    }
    if (!found) break
  }

  // hats: compare with what was available the previous active day, so seasonal hats get announced too
  const prevNow = prevQuestDay && prevQuestDay !== today ? parseDay(prevQuestDay)?.getTime() ?? now : now
  const had = new Set(availableHats(before, prevNow))
  const avail = availableHats(p, now)
  const unlockedHats = avail.filter(h => !had.has(h))
  if (p.hat && !avail.includes(p.hat)) p.hat = null // a seasonal hat went out of season

  const oldLevel = levelOf(before.xp).level
  const newLevel = levelOf(p.xp).level
  return { profile: p, xpGained: xp, unlocked, levelUp: newLevel !== oldLevel ? newLevel : null, completedQuests, unlockedHats }
}

// ---------- small UI helpers ----------

export function streakLabel(profile: Profile, now: number): string {
  const today = dayOf(now)
  const { count: n, lastDay } = profile.streak
  if (n > 0 && lastDay === today) return n === 1 ? 'Day 1 of a new streak' : `${n}-day streak`
  if (n > 0 && lastDay && continues(lastDay, today)) {
    const d = parseDay(today)
    if (d && isWeekend(d)) return `Back Monday to keep your ${n}-day streak`
    return `${n}-day streak, keep it alive today`
  }
  return 'No streak yet, start one today'
}

// True when every daily quest of today is done (the Daily Sweep was earned, claimed or not).
export function sweptToday(profile: Profile, now: number): boolean {
  return profile.quests.day === dayOf(now) && profile.quests.items.length >= 3 && profile.quests.items.every(q => q.done)
}

// True while today's Daily Sweep bonus waits for its claim; it expires at midnight.
export function sweepClaimable(profile: Profile, now: number): boolean {
  return sweptToday(profile, now) && profile.sweepClaimed !== dayOf(now)
}

// How many Daily Sweeps the profile has collected.
export function sweepsOf(profile: Profile): number {
  return (profile as Stored).sweeps ?? 0
}

export function equipHat(profile: Profile, hat: HatId | null, now: number): Profile {
  if (hat !== null && !availableHats(profile, now).includes(hat)) return profile
  return { ...clone(profile), hat }
}

