import type { DecorChoice, DecorSlot, HatId, Profile } from '../types'
import { availableHats, HATS, levelOf } from './game'

// Room decor Clawd unlocks with levels and achievements; the person picks one variant per slot.

export type DecorItem = {
  slot: DecorSlot
  id: string
  name: string
  requirement: string
  level?: number
  achievement?: string
}

export const SLOTS: Array<{ slot: DecorSlot; label: string }> = [
  { slot: 'drink', label: 'Desk drink' },
  { slot: 'plant', label: 'Plant' },
  { slot: 'poster', label: 'Poster' },
  { slot: 'rug', label: 'Rug' },
  { slot: 'shelf', label: 'Shelf top' },
  { slot: 'companion', label: 'Roommate' },
]

export const DECOR: DecorItem[] = [
  { slot: 'drink', id: 'coffee', name: 'Coffee', requirement: 'Always there for you' },
  { slot: 'drink', id: 'tea', name: 'Tea', requirement: 'Level 3', level: 3 },
  { slot: 'drink', id: 'energy', name: 'Clawd Energy', requirement: 'Level 5', level: 5 },
  { slot: 'drink', id: 'espresso', name: 'Triple Espresso', requirement: 'Trophy: Night Owl', achievement: 'night-owl' },
  { slot: 'drink', id: 'boba', name: 'Boba Tea', requirement: 'Level 12', level: 12 },

  { slot: 'plant', id: 'fern', name: 'Fern', requirement: 'Grows as you finish requests' },
  { slot: 'plant', id: 'cactus', name: 'Cactus', requirement: 'Level 4', level: 4 },
  { slot: 'plant', id: 'sunflower', name: 'Sunflower', requirement: 'Trophy: Seven Days Strong', achievement: 'streak-7' },
  { slot: 'plant', id: 'monstera', name: 'Monstera', requirement: 'Trophy: Bookworm', achievement: 'bookworm' },
  { slot: 'plant', id: 'bonsai', name: 'Bonsai', requirement: 'Level 10', level: 10 },

  { slot: 'poster', id: 'none', name: 'Bare wall', requirement: 'Minimalism' },
  { slot: 'poster', id: 'space', name: 'Space Clawd', requirement: 'Level 5', level: 5 },
  { slot: 'poster', id: 'terminal', name: 'Terminal', requirement: 'Trophy: Hundred Club', achievement: 'hundred-club' },
  { slot: 'poster', id: 'cat', name: 'Cat Poster', requirement: 'Trophy: Hello World', achievement: 'hello-world' },
  { slot: 'poster', id: 'wave', name: 'The Great Wave', requirement: 'Level 9', level: 9 },
  { slot: 'poster', id: 'clawd', name: 'Self Portrait', requirement: 'Level 15', level: 15 },

  { slot: 'rug', id: 'none', name: 'Bare floor', requirement: 'Minimalism' },
  { slot: 'rug', id: 'stripes', name: 'Striped Rug', requirement: 'Level 3', level: 3 },
  { slot: 'rug', id: 'round', name: 'Round Rug', requirement: 'Level 6', level: 6 },
  { slot: 'rug', id: 'checker', name: 'Diner Checker', requirement: 'Trophy: Clean Sweep', achievement: 'clean-sweep' },

  { slot: 'shelf', id: 'none', name: 'Empty', requirement: 'Minimalism' },
  { slot: 'shelf', id: 'duck', name: 'Rubber Duck', requirement: 'Trophy: Rubber Duck', achievement: 'rubber-duck' },
  { slot: 'shelf', id: 'globe', name: 'Globe', requirement: 'Trophy: Explorer', achievement: 'explorer' },
  { slot: 'shelf', id: 'lava', name: 'Lava Lamp', requirement: 'Level 8', level: 8 },
  { slot: 'shelf', id: 'boombox', name: 'Boombox', requirement: 'Level 14', level: 14 },

  { slot: 'companion', id: 'none', name: 'Nobody', requirement: 'Peace and quiet' },
  { slot: 'companion', id: 'fishbowl', name: 'Goldfish', requirement: 'Trophy: Polite', achievement: 'polite' },
  { slot: 'companion', id: 'cat', name: 'Cat', requirement: 'Level 10', level: 10 },
  { slot: 'companion', id: 'roomba', name: 'Robot Vacuum', requirement: 'Trophy: Thousand Hands', achievement: 'thousand-hands' },
]

export function isUnlocked(item: DecorItem, profile: Profile): boolean {
  if (item.level !== undefined && levelOf(profile.xp).level < item.level) return false
  if (item.achievement !== undefined && profile.achievements[item.achievement] === undefined) return false
  return true
}

// Hats that a level alone unlocks (some also have another way in, see availableHats).
const HAT_LEVELS: Partial<Record<HatId, number>> = { party: 2, wizard: 10, crown: 25 }

// The closest thing a level-up will bring: lowest level above the current one, decor first on ties.
export function nextUnlock(profile: Profile): { name: string; level: number } | undefined {
  const level = levelOf(profile.xp).level
  const owned = new Set(availableHats(profile, 0))
  const candidates = [
    ...DECOR.filter(d => d.level !== undefined).map(d => ({ name: d.name, level: d.level! })),
    ...HATS.filter(hat => HAT_LEVELS[hat.id] !== undefined && !owned.has(hat.id)).map(hat => ({ name: hat.name, level: HAT_LEVELS[hat.id]! })),
  ]
  let best: { name: string; level: number } | undefined
  for (const c of candidates) if (c.level > level && (!best || c.level < best.level)) best = c
  return best
}

// Items newly available after an event, for a toast. Minimalism options are not news.
export function newlyUnlocked(before: Profile, after: Profile): DecorItem[] {
  return DECOR.filter(item => item.id !== 'none' && item.id !== 'coffee' && item.id !== 'fern' && !isUnlocked(item, before) && isUnlocked(item, after))
}

// What the room shows: the person's pick when still unlocked, else what the room had before decor existed.
export function resolveDecor(choice: DecorChoice, profile: Profile): Required<DecorChoice> {
  const level = levelOf(profile.xp).level
  const auto: Required<DecorChoice> = {
    drink: 'coffee',
    plant: 'fern',
    poster: level >= 5 ? 'space' : 'none',
    rug: level >= 3 ? 'stripes' : 'none',
    shelf: level >= 8 ? 'lava' : 'none',
    companion: 'none',
  }
  const out = { ...auto }
  for (const { slot } of SLOTS) {
    const id = choice[slot]
    const item = DECOR.find(d => d.slot === slot && d.id === id)
    if (item && isUnlocked(item, profile)) out[slot] = item.id
  }
  return out
}

export function migrateDecor(raw: unknown): DecorChoice {
  if (!raw || typeof raw !== 'object') return {}
  const out: DecorChoice = {}
  for (const { slot } of SLOTS) {
    const id = (raw as Record<string, unknown>)[slot]
    if (typeof id === 'string' && DECOR.some(d => d.slot === slot && d.id === id)) out[slot] = id
  }
  return out
}

