      break
    case 'pumpkin':
      body = hatMap(['.....gg.....', '..oOooooOo..', '.oOYYooYYOo.', '.oOooYYooOo.', '.oOYYYYYYOo.', '..oOooooOo..'], { o: '#F08A2A', O: '#C86A1E', Y: '#FFD54A', g: '#6E9B5E' })
      break
    case 'beanie':
