      break
    case 'tophat':
      body = hatMap(['..kkkkkkkh..', '..kkkkkkkh..', '..kkkkkkkh..', '..rrrrrrrr..', '..kkkkkkkh..', 'kkkkkkkkkkkk'], { k: '#3C3C44', h: '#6A6A75', r: RED })
      break
    case 'halo':
      body = `<g class="halo">` + R(38, -30, 68, 16, '#F6D365', op(0.18)) +
        R(44, -30, 56, 4, '#F6D365') + R(44, -18, 56, 4, '#F6D365') + R(36, -26, 8, 8, '#F6D365') + R(100, -26, 8, 8, '#F6D365') + `</g>`
      break
    case 'propeller':
      body = hatMap(['....ryyb....', '..rrryybbb..', '.rrrryybbbb.', 'rrrrryybbbbb'], { r: '#D23C3C', y: '#F2C230', b: '#4F6BD8' }) +
        R(68, -40, 8, 12, '#6A6A75') +
        `<g class="prop fb">${R(36, -46, 72, 6, BLUE)}${R(36, -46, 10, 6, '#D23C3C')}${R(98, -46, 10, 6, '#D23C3C')}</g>` +
        R(64, -48, 16, 8, GOLD)
      break
  }
  return `<g class="hat">${body}</g>`
}

function clawd(mood: Mood, hat: AnyHat, tint?: string): string {
  const c = tint ?? (mood === 'error' ? RED : ORANGE)
  return `<g class="crab fbB">` +
    P(3, 0, 12, 4, c) +
    P(1, 2, 2, 1, c, 'aL fbR') + P(15, 2, 2, 1, c, 'aR fbL') +
    P(4, 4, 1, 1, c, 'lg l0 fbT') + P(6, 4, 1, 1, c, 'lg l1 fbT') + P(11, 4, 1, 1, c, 'lg l2 fbT') + P(13, 4, 1, 1, c, 'lg l3 fbT') +
    (tint ? `<g class="ey fb">${P(5, 1, 1, 1, INK)}${P(12, 1, 1, 1, INK)}</g>` : eyes(mood)) +
    (mood === 'happy' && !tint ? R(26, 26, 10, 4, '#F2A0A0') + R(108, 26, 10, 4, '#F2A0A0') : '') +
    (tint ? '' : hatSvg(hat)) +
    `</g>`
}

// ---------- shared CSS (sprite + hats), identical in every SVG this file emits ----------

const SPRITE_CSS = `
