function trophy(i: number, x: number, base: number, newest: boolean): string {
  const color = i < 4 ? BRONZE : i < 8 ? SILVER : GOLD
  const dark = shade(color, -0.3)
  const light = shade(color, 0.45)
  let out: string
  if (i % 3 === 2) {
    // medal on a ribbon
    const y = base - 14
    out = R(x + 1, y, 3, 6, '#C8553D') + R(x + 6, y, 3, 6, '#4F6BD8') +
      R(x + 3, y + 5, 4, 1, dark) + R(x + 2, y + 6, 6, 7, color) + R(x + 3, y + 13, 4, 1, dark) +
      R(x + 4, y + 8, 2, 3, light) + R(x + 1, y + 7, 1, 5, color) + R(x + 8, y + 7, 1, 5, color)
  } else {
    const y = base - 14
    out = R(x, y, 10, 2, color) + R(x + 1, y + 2, 8, 4, color) + R(x - 2, y + 1, 2, 4, dark) + R(x + 10, y + 1, 2, 4, dark) +
      R(x + 3, y + 6, 4, 2, color) + R(x + 4, y + 8, 2, 2, dark) + R(x + 2, y + 10, 6, 2, color) + R(x + 1, y + 12, 8, 2, dark) +
      R(x + 2, y + 2, 1.5, 3, light)
  }
  if (newest) out += `<g class="sk">${R(x + 9, base - 18, 1.5, 5, '#FFF7C8')}${R(x + 7.25, base - 16.25, 5, 1.5, '#FFF7C8')}</g>`
  return out
}

function trophyShelf(count: number): string {
  let out = R(296, 58, 100, 3, WOOD) + R(300, 61, 3, 4, WOOD_D) + R(389, 61, 3, 4, WOOD_D) +
    R(296, 96, 100, 3, WOOD) + R(300, 99, 3, 4, WOOD_D) + R(389, 99, 3, 4, WOOD_D)
  const shown = Math.min(12, count)
  for (let i = 0; i < 12; i++) {
    const x = 301 + (i % 6) * 16
    const base = i < 6 ? 96 : 58
    out += i < shown ? trophy(i, x, base, i === shown - 1) : R(x + 2, base - 2, 6, 2, DIM, op(0.3))
  }
  if (count > 12) out += `<g class="sk">${R(392, 40, 1.5, 6, GOLD)}${R(389.75, 42.25, 6, 1.5, GOLD)}</g>`
  return out
