        R(67, -38, 6, 6, INK, cls('d0')) + R(77, -38, 6, 6, INK, cls('d1')) + R(87, -38, 6, 6, INK, cls('d2'))
    case 'reading':
      return `<g class="hd">${R(14, 12, 44, 14, '#C9A45B')}${R(16, 11, 19, 13, PAPER)}${R(37, 11, 19, 13, '#D8D5C8')}${R(35, 11, 2, 14, '#9A8F7A')}` +
