// Pixel art for the swappable room decor. Coordinates are in scene.ts's 400x260 room.
// Each function draws one slot's variant; scene.ts falls back to its own default when the id is unknown.

const ORANGE = '#D97757'
const INK = '#1F1E1D'
const PAPER = '#E8E6DC'
const WOOD = '#6B4A35'
const WOOD_D = '#4E3526'
const METAL = '#5A5A55'
const SILVER = '#C3C8CE'
const GOLD = '#E2B84A'
const PINK = '#E5677E'
const LEAF = '#6E9B5E'
const LEAF_L = '#7FB06D'
const LEAF_D = '#4C7F45'

function R(x: number, y: number, w: number, h: number, fill: string, extra = ''): string {
  return `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${fill}"${extra}/>`
}

const cls = (c: string): string => ` class="${c}"`
const op = (o: number): string => ` opacity="${o}"`

function pmap(rows: readonly string[], x0: number, y0: number, u: number, pal: Record<string, string>): string {
  let out = ''
  rows.forEach((row, j) => {
    let i = 0
    while (i < row.length) {
      const ch = row[i]!
      let k = i
      while (k < row.length && row[k] === ch) k++
      const fill = pal[ch]
      if (fill) out += R(x0 + i * u, y0 + j * u, (k - i) * u, u, fill)
      i = k
    }
  })
  return out
}

// ---------- drinks (desk, right of the monitor; the desk top is y=196) ----------

export function drinkSvg(kind: string, fill: number): string {
  switch (kind) {
    case 'tea': {
      const h = [0, 4, 7, 10][fill] ?? 0
      return R(357, 182, 8, 12, '#BFE3F5', op(0.25)) +
        (h > 0 ? R(357, 194 - h, 8, h, '#C98A3A', op(0.9)) : '') +
        R(355, 182, 2, 14, '#D8EEF7', op(0.8)) + R(365, 182, 2, 14, '#D8EEF7', op(0.8)) + R(355, 194, 12, 2, '#D8EEF7', op(0.8)) +
        R(367, 185, 3, 2, '#D8EEF7', op(0.8)) + R(369, 185, 2, 8, '#D8EEF7', op(0.8)) + R(367, 191, 3, 2, '#D8EEF7', op(0.8)) +
        R(363, 178, 1, 10, PAPER) + R(362, 187, 4, 5, PINK) +
        (h > 0 ? `<g${op(0.5)}>${R(358, 174, 2, 6, PAPER, cls('stm'))}${R(361, 170, 2, 6, PAPER, cls('stm s2'))}</g>` : '')
    }
    case 'energy':
      // a tall can of Clawd Energy
      return R(357, 178, 10, 18, '#2A2A2E') + R(357, 177, 10, 2, SILVER) + R(357, 195, 10, 1, SILVER) +
        R(357, 183, 10, 7, ORANGE) + pmap(['..y', '.y.', 'yyy', '.y.', 'y..'], 359, 183, 1.4, { y: '#FFE14D' }) +
        R(365, 179, 1, 15, '#FFFFFF', op(0.18)) + R(361, 175, 3, 2, SILVER) +
        (fill > 0 ? `<g${op(0.7)}>${R(360, 172, 1.5, 1.5, '#FFE14D', cls('fz'))}${R(363, 170, 1.5, 1.5, '#FFE14D', cls('fz s2'))}</g>` : '')
    case 'boba': {
      const h = [2, 6, 10, 13][fill] ?? 2
      return R(357, 180, 11, 16, PAPER, op(0.18)) + R(357, 196 - h, 11, h, '#C69C6D') +
        R(358, 193, 2, 2, INK) + R(361, 194, 2, 2, INK) + R(364, 193, 2, 2, INK) + R(360, 191, 2, 2, INK) +
        R(356, 179, 13, 2, PAPER) + R(355, 181, 1, 15, PAPER, op(0.5)) + R(368, 181, 1, 15, PAPER, op(0.5)) +
        R(364, 166, 2, 13, PINK) + R(364, 166, 4, 2, PINK)
    }
    case 'espresso':
      // three tiny cups, one stacked on another: it is that kind of night (x 356..376: clear of the papers and a second monitor)
      return ([[357, 189], [367, 189], [357, 182]] as const).map(([x, y], i) =>
        R(x, y, 7, 6, PAPER) + R(x + 7, y + 1, 2, 3, PAPER) + R(x - 1, y + 6, 10, 1, PAPER) +
        (i === 2 && fill > 0 ? R(x + 1, y, 5, 1, '#6B3F27') + `<g${op(0.5)}>${R(x + 2, y - 7, 1.5, 5, PAPER, cls('stm'))}</g>` : ''),
      ).join('')
    default:
