  }
}

// ---------- plants (pot centred on x=94, soil at y=210) ----------

const POT = R(84, 214, 20, 18, '#8A5A44') + R(82, 210, 24, 6, '#A06A50') + R(86, 216, 3, 12, '#A06A50', op(0.6))

export function plantSvg(kind: string, stage: number): string {
  const s = Math.max(0, Math.min(4, stage))
  let g = ''
  switch (kind) {
    case 'cactus': {
      const h = [6, 14, 22, 30, 36][s]!
      g = R(90, 210 - h, 8, h, '#5E9A5A') + R(91, 210 - h, 2, h, '#7DB872') + R(90, 210 - h, 8, 1, '#7DB872')
      if (s >= 2) g += R(84, 210 - h * 0.55, 6, 3, '#5E9A5A') + R(84, 210 - h * 0.55 - 8, 3, 8, '#5E9A5A')
      if (s >= 3) g += R(98, 210 - h * 0.7, 6, 3, '#5E9A5A') + R(101, 210 - h * 0.7 - 7, 3, 7, '#5E9A5A')
      for (let y = 212 - h; y < 208; y += 5) g += R(97, y, 1, 1, PAPER) + R(89, y + 2, 1, 1, PAPER)
      if (s >= 4) g += R(92, 210 - h - 4, 4, 4, PINK) + R(93, 210 - h - 5, 2, 1, '#F2A7C3')
      break
    }
    case 'bonsai': {
      g = R(92, 198, 4, 12, WOOD) + R(88, 200, 4, 2, WOOD) + R(96, 194, 5, 2, WOOD)
      const blobs: Array<[number, number, number]> = [[82, 190, 14], [94, 184, 14], [80, 180, 12], [92, 174, 12], [86, 168, 14]]
      blobs.slice(0, s + 1).forEach(([x, y, w], i) => {
        g += R(x, y, w, 7, i % 2 ? LEAF : LEAF_D) + R(x + 2, y - 2, w - 4, 2, LEAF_L)
      })
      break
    }
    case 'sunflower': {
      const h = [8, 20, 32, 44, 54][s]!
      g = R(93, 210 - h, 2, h, LEAF) + R(86, 200, 7, 3, LEAF_L) + (s >= 2 ? R(95, 194, 7, 3, LEAF) : '')
      if (s >= 1) {
        const y = 210 - h - 8
        const big = s >= 3 ? 1 : 0
        g += `<g class="sfh">${R(88 - big, y - big, 12 + big * 2, 12 + big * 2, '#F6C445')}${R(86 - big, y + 3, 16 + big * 2, 6, '#F6C445')}` +
          `${R(91 - big, y - 2 - big, 6 + big * 2, 16 + big * 2, '#F6C445')}${R(91, y + 3, 6, 6, '#6B3F27')}${R(92, y + 4, 2, 2, '#8A5A3A')}</g>`
      }
      break
    }
    case 'monstera': {
      const leaves: Array<[number, number, boolean]> = [[78, 196, false], [96, 190, true], [80, 180, false], [98, 172, true], [84, 164, false]]
      g = R(93, 210 - (s + 1) * 9, 2, (s + 1) * 9, LEAF_D)
      leaves.slice(0, s + 1).forEach(([x, y, right], i) => {
        const c = i % 2 ? LEAF : LEAF_D
        g += R(x, y, 14, 9, c) + R(x + (right ? 0 : 2), y - 2, 12, 2, c) + R(x + 4, y + 2, 2, 3, '#2B3A28', op(0.6)) + R(x + 9, y + 4, 2, 3, '#2B3A28', op(0.6))
      })
      break
    }
    default:
      return ''
  }
  return `<g class="lfg">${g}</g>${POT}`
}

