  let out = R(264, 26, 28, 38, fr) + (gold ? R(264, 26, 28, 2, '#F6D88A') + R(264, 26, 2, 38, '#F6D88A') : '') + inner
  if (gold) out += `<g class="sk">${R(289, 22, 1.5, 6, '#FFF7C8')}${R(286.75, 24.25, 6, 1.5, '#FFF7C8')}</g>`
  return out
}

// ---------- rugs (floor, y 234..240) ----------

